  // ============ 经典例题 ============
  const EXAMPLE = {
    pd01: { q: R`设某厂商生产函数 $Q=2L^{0.5}K^{0.5}$。(1) 求 $L=K=4$ 时的产量；(2) 求劳动的边际产量 $MP_{L}$ 与资本的边际产量 $MP_{K}$；(3) 判断该生产函数的规模报酬性质。`,
      a: R`(1) $$Q=2\cdot\sqrt{4}\cdot\sqrt{4}=8$$ (2) $$MP_{L}=\frac{\partial Q}{\partial L}=K^{0.5}L^{-0.5},\qquad MP_{K}=\frac{\partial Q}{\partial K}=L^{0.5}K^{-0.5}$$ (3) $$Q(\lambda L,\lambda K)=2(\lambda L)^{0.5}(\lambda K)^{0.5}=\lambda\cdot2L^{0.5}K^{0.5}=\lambda Q$$ 因 $\alpha+\beta=0.5+0.5=1$，规模报酬不变。` },
    pd02: { q: R`设生产函数 $Q=3L+2L^{2}-L^{3}$。(1) 求边际产量 $MP_{L}$；(2) 求边际产量最大时的劳动投入量，并说明此后 $MP_{L}$ 如何变化。`,
      a: R`(1) $$MP_{L}=\frac{dQ}{dL}=3+4L-3L^{2}$$ (2) 令 $$\frac{dMP_{L}}{dL}=4-6L=0\Rightarrow L=\frac{2}{3}$$ 当 $L>\frac{2}{3}$ 时 $MP_{L}$ 随 $L$ 增大而递减，体现了边际报酬递减规律。` },
    pd03: { q: R`设短期生产函数 $Q=L^{2}-0.2L^{3}$。(1) 求平均产量 $AP_{L}$；(2) 求平均产量最大时的劳动投入量，并验证此时 $MP_{L}=AP_{L}$。`,
      a: R`(1) $$AP_{L}=\frac{Q}{L}=L-0.2L^{2}$$ (2) 令 $$\frac{dAP_{L}}{dL}=1-0.4L=0\Rightarrow L=2.5$$ 又 $$MP_{L}=\frac{dQ}{dL}=2L-0.6L^{2}$$ 当 $L=2.5$ 时，$MP_{L}=5-3.75=1.25$，$AP_{L}=2.5-1.25=1.25$，故 $MP_{L}=AP_{L}$，平均产量在边际产量与其相交处取最大值。` },
    pd04: { q: R`判断 $Q=2L^{0.5}K^{0.5}$ 中劳动的边际产量是否递减`,
      a: R`$$MP_{L}=K^{0.5}L^{-0.5}$$ 随 $L$ 增大而递减，符合边际报酬递减。` },
    pd07: { q: R`设生产函数 $Q=L^{0.5}K^{0.5}$。(1) 求边际技术替代率 $MRTS_{LK}$；(2) 求 $L=1,\ K=4$ 时其值并解释含义；(3) 说明 $L$ 增大时 $MRTS_{LK}$ 如何变化。`,
      a: R`(1) $$MRTS_{LK}=\frac{MP_{L}}{MP_{K}}=\frac{K}{L}$$ (2) 当 $L=1,\ K=4$ 时，$MRTS_{LK}=\frac{4}{1}=4$，即此时多投入 1 单位劳动可少投入 4 单位资本而产量不变。(3) $L$ 增大时 $MRTS_{LK}=\frac{K}{L}$ 递减（等产量线凸向原点），符合边际技术替代率递减规律。` },
    pd09: [{ q: R`分别判断下列生产函数的规模报酬性质：(1) $Q=L^{0.6}K^{0.6}$；(2) $Q=L^{0.4}K^{0.6}$；(3) $Q=L^{0.3}K^{0.4}$。`,
      a: R`(1) $0.6+0.6=1.2>1$，规模报酬递增；(2) $0.4+0.6=1$，规模报酬不变；(3) $0.3+0.4=0.7<1$，规模报酬递减。` },
    { q: R`（2015 真题）已知生产函数 $f(x_{1},x_{2})=\min\{x_{1},\,x_{2}^{\alpha}\}$（$\alpha>0$）。求规模报酬递增、不变、递减时 $\alpha$ 的取值范围。`,
      a: R`$$f(tx_{1},tx_{2})=\min\{tx_{1},\,t^{\alpha}x_{2}^{\alpha}\},\qquad tf=\min\{tx_{1},\,tx_{2}^{\alpha}\}$$ 比较二者：$\alpha>1$ 时 $t^{\alpha}>t$，$f(tx)>tf$，规模报酬递增；$\alpha=1$ 时 $t^{\alpha}=t$，规模报酬不变；$0<\alpha<1$ 时 $t^{\alpha}<t$，规模报酬递减。`,
      src: '2015 北大光华 431 真题' } ],
    pd10: { q: R`判断 $Q=L^{0.4}K^{0.6}$ 的规模报酬`,
      a: R`$0.4+0.6=1$，规模报酬不变。` },
    pd11: { q: R`设工资 $w=2$，资本价格 $r=4$，总成本 $C=80$。(1) 写出等成本线方程；(2) 求其斜率；(3) 若成本增至 $C=120$，等成本线如何移动？`,
      a: R`(1) $$2L+4K=80$$ (2) 化为 $K=20-\frac{1}{2}L$，斜率 $$-\frac{w}{r}=-\frac{2}{4}=-\frac{1}{2}$$ (3) 成本增至 120 时等成本线为 $2L+4K=120$，向外（右上方）平移，斜率不变。` },
    pd12: { q: R`设 $Q=LK,\ w=r=2$，求生产 $Q=4$ 的最小成本要素组合`,
      a: R`$\frac{MP_{L}}{MP_{K}}=\frac{K}{L}=\frac{w}{r}=1\Rightarrow L=K$，又 $LK=4$，故 $L=K=2$，$C=2\cdot2+2\cdot2=8$。` },
    ct01: { q: R`某厂商短期总成本函数 $STC=100+2Q+Q^{2}$。(1) 指出其中的固定成本 $FC$ 与可变成本 $VC$；(2) 求 $Q=10$ 时的总成本及对应的 $FC$、$VC$。`,
      a: R`(1) $$FC=100,\qquad VC=2Q+Q^{2}$$ (2) 当 $Q=10$ 时，$$TC=100+2\times10+100=220,\quad FC=100,\quad VC=120$$` },
    ct02: [{ q: R`某厂商总成本 $TC=100+2Q+Q^{2}$。(1) 求平均成本 $AC$；(2) 求 $AC$ 最小时的产量；(3) 验证该产量下 $MC=AC$。`,
      a: R`(1) $$AC=\frac{TC}{Q}=\frac{100}{Q}+2+Q$$ (2) 令 $$\frac{dAC}{dQ}=-\frac{100}{Q^{2}}+1=0\Rightarrow Q=10$$ (3) $$MC=\frac{dTC}{dQ}=2+2Q$$ 当 $Q=10$ 时，$MC=22$，$AC=\frac{100}{10}+2+10=22$，故 $MC=AC$，平均成本在边际成本与其相交处取最小值。` },
    { q: R`（2015 真题）已知生产函数 $f(x_{1},x_{2})=\min\{x_{1},\,x_{2}^{\alpha}\}$（$\alpha>0$），要素价格 $w_{1}=10,\ w_{2}=20$，其成本函数为 $C(q)=10q+20q^{1/\alpha}$。求平均成本函数 $AC(q)$。`,
      a: R`$$AC(q)=\frac{C(q)}{q}=10+20q^{\frac{1}{\alpha}-1}=10+\frac{20}{q^{1-\frac1\alpha}}$$ $\alpha>1$（规模报酬递增）时 $AC$ 随 $q$ 递减；$\alpha=1$ 时 $AC=30$ 恒定；$0<\alpha<1$ 时 $AC$ 递增——平均成本与规模报酬直接对应。`,
      src: '2015 北大光华 431 真题' } ],
    ct05: { q: R`IBM 生产某型号计算机，产量范围 $200\sim700$，总成本函数 $C=28303800+460800Q$。(1) 求边际成本 $MC$ 与平均成本 $AC$；(2) 说明该成本函数下 $MC$ 与 $AC$ 随产量如何变化。`,
      a: R`(1) $$MC=\frac{dC}{dQ}=460800$$（常数）；$$AC=\frac{C}{Q}=\frac{28303800}{Q}+460800$$。(2) $MC$ 恒为常数 $460800$；$AC$ 随 $Q$ 增大而递减（固定成本被摊薄），并逐渐逼近 $MC$。`,
      src: '名校考研真题（厉以宁《西方经济学》题库·IBM 成本）' },
    ct06: { q: R`当 $MC<AC$ 时，平均成本如何变化？`,
      a: R`$MC<AC$ 时 $AC$ 下降（$MC$ 曲线从下方穿过 $AC$ 最低点）。` },
    ct14: { q: R`完全竞争下，当 $P<AVC_{\min}$ 时厂商应如何决策？`,
      a: R`停产（停业），因为连可变成本都无法弥补。` },
    ct15: { q: R`当 $P=AC_{\min}$ 时厂商的经济利润`,
      a: R`经济利润为零（盈亏平衡点）。` },
    pd18: { q: R`成本最小化得到的要素需求 $L(w,r,Q)$ 称为什么？`,
      a: R`条件要素需求函数（只取决于产量与要素价格）。` },
    pd20: [{ q: R`完全竞争 $P=10$，生产函数 $Q=L^{0.5}$，工资 $w=1$，求最优劳动投入`,
      a: R`$$P\cdot MP_{L}=w\Rightarrow 10\cdot\frac{1}{2\sqrt{L}}=1\Rightarrow L=25$$` },
    { q: R`（2020 真题）企业 A 生产函数 $y_{a}=2(L_{a})^{0.5}$、企业 B 生产函数 $y_{b}=(L_{b})^{0.5}$，产品价格 $p=30$、工资 $w=5$，两企业分别最大化利润。求各自的利润最大化雇佣量。`,
      a: R`完全竞争要素使用条件 $P\cdot MP_{L}=w$：A 企业 $$30\cdot L_{a}^{-0.5}=5\Rightarrow L_{a}=36$$ B 企业 $$30\cdot\tfrac12 L_{b}^{-0.5}=15L_{b}^{-0.5}=5\Rightarrow L_{b}=9$$ 要素需求按边际产品价值等于要素价格确定。`,
      src: '2020 北大光华 431 真题' } ],
    rv01: [{ q: R`某厂商面临需求曲线 $P=50-2Q$。(1) 求总收益函数 $TR$；(2) 求 $Q=10$ 时的价格与总收益；(3) 求边际收益 $MR$，并说明该厂商是否面临向右下方倾斜的需求曲线。`,
      a: R`(1) $$TR=P\cdot Q=(50-2Q)Q=50Q-2Q^{2}$$ (2) 当 $Q=10$ 时，$P=50-20=30$，$$TR=30\times10=300$$ (3) $$MR=\frac{dTR}{dQ}=50-4Q$$ $MR$ 随 $Q$ 递减且低于价格，说明厂商面临向右下方倾斜的需求曲线，具有市场势力。` },
    { q: R`（2026 真题）企业边际成本 $MC=10$。国内市场消费者购买 $x$ 单位商品的效用为 $26x-2x^{2}$（反需求 $P_{d}=26-4x$）。写出国内市场的总收益函数与边际收益函数。`,
      a: R`$$TR_{d}=P_{d}\cdot x=(26-4x)x=26x-4x^{2},\qquad MR_{d}=\frac{dTR}{dx}=26-8x$$ 反需求线向下倾斜、$MR$ 低于价格，厂商具有市场势力（国外市场反需求为 $P_{f}=14-2x$，需求更平缓）。`,
      src: '2026 北大光华 431 真题' } ],
    rv02: { q: R`设 $TR=50$，$Q=10$，求平均收益 $AR$`,
      a: R`$$AR=\frac{TR}{Q}=5$$` },
    rv03: [{ q: R`垄断厂商需求 $P=100-2Q$。(1) 求总收益 $TR$ 与边际收益 $MR$；(2) 求 $Q=20$ 时的 $MR$；(3) 说明垄断厂商的 $MR$ 为何小于价格。`,
      a: R`(1) $$TR=P Q=100Q-2Q^{2},\qquad MR=\frac{dTR}{dQ}=100-4Q$$ (2) 当 $Q=20$ 时，$MR=100-80=20$。(3) 降价多卖一单位会使此前所有单位都降价，故 $$MR=P+Q\frac{dP}{dQ}<P$$ 此处 $\frac{dP}{dQ}=-2$，故 $MR$ 低于价格。` },
    { q: R`（2014 真题）垄断厂商需求 $Q=144/P^2$（即反需求 $P=12Q^{-1/2}$）。求总收益函数 $TR$ 与边际收益 $MR$。`,
      a: R`$$TR=P Q=12Q^{1/2},\qquad MR=\frac{dTR}{dQ}=6Q^{-1/2}$$ 恒弹性（$|\varepsilon|=2$）需求下 $MR=P\left(1-\frac12\right)=\frac{P}{2}$，边际收益低于价格。`,
      src: '2014 北大光华 431 真题' } ],
    rv04: { q: R`设 $TR=100Q-Q^{2},\ TC=20Q$，求利润 $\pi$`,
      a: R`$$\pi=TR-TC=80Q-Q^{2}$$` },
    rv05: { q: R`经济利润与会计利润的差别在于？`,
      a: R`经济利润还扣除隐成本（机会成本），会计利润只扣显成本。` },
    rv06: { q: R`需求 $P=100-Q$，$MC=20$，求利润最大化产量`,
      a: R`$$MR=100-2Q=MC=20\Rightarrow Q=40$$` },
    cu01: { q: R`总效用 $TU$ 与边际效用 $MU$ 的关系`,
      a: R`$$MU=\frac{dTU}{dQ}$$` },
    cu02: { q: R`某人消费某商品的总效用 $TU=14Q-Q^{2}$。(1) 求边际效用 $MU$；(2) 求消费第 3 个单位带来的边际效用；(3) 判断 $MU$ 是否递减。`,
      a: R`(1) $$MU=\frac{dTU}{dQ}=14-2Q$$ (2) 第 3 个单位：$MU=14-2\times3=8$。(3) $$\frac{dMU}{dQ}=-2<0$$ $MU$ 随 $Q$ 增加而递减，符合边际效用递减规律。` },
    cu04: [{ q: R`$MU_{1}=20,\ MU_{2}=10,\ P_{1}=4,\ P_{2}=2$，判断是否达到消费者均衡`,
      a: R`$$\frac{MU_{1}}{P_{1}}=5=\frac{MU_{2}}{P_{2}}$$ 已达均衡。` },
    { q: R`（2013 真题）大米 $x_{1}$ 每单位需 2 元货币+1 元粮票，油 $x_{2}$ 每单位需 1 元货币+1 元粮票，货币与粮票可按 1:1 互换（持有货币 60、粮票 30），效用 $U=10x_{2}+x_{1}x_{2}$。已知最优消费量为 $x_{1}=10,\ x_{2}=30$，验证此时达到消费者均衡。`,
      a: R`有效价格：大米 $P_{1}=2+1=3$，油 $P_{2}=1+1=2$。$$MU_{1}=\frac{\partial U}{\partial x_{1}}=x_{2}=30,\qquad MU_{2}=\frac{\partial U}{\partial x_{2}}=10+x_{1}=20$$ $$\frac{MU_{1}}{P_{1}}=\frac{30}{3}=10=\frac{MU_{2}}{P_{2}}=\frac{20}{2}$$ 每元货币的边际效用相等，且预算用尽（$3\times10+2\times30=90=60+30$），达到消费者均衡。`,
      src: '2013 北大光华 431 真题' } ],
    cu05: { q: R`某人持有货币 60 元、粮票 30 元。大米 $x_{1}$ 每单位需 2 元货币 + 1 元粮票，油 $x_{2}$ 每单位需 1 元货币 + 1 元粮票，效用函数 $U=10x_{2}+x_{1}x_{2}$。(1) 货币与粮票不可互换时，写出预算约束集并求最优消费组合；(2) 货币与粮票可按 1:1 互换时，求最优消费组合，并说明该人会用货币换多少粮票。`,
      a: R`(1) 货币约束 $$2x_{1}+x_{2}\le60$$，粮票约束 $$x_{1}+x_{2}\le30$$。因 $x_{1}\le30$ 时恒有 $30-x_{1}\le60-2x_{1}$，故粮票约束先达到，$x_{2}=30-x_{1}$。代入 $$U=10(30-x_{1})+x_{1}(30-x_{1})=300+20x_{1}-x_{1}^{2}$$，令 $$\frac{dU}{dx_{1}}=20-2x_{1}=0\Rightarrow x_{1}=10,\ x_{2}=20,\ U=400$$（货币仅用 40 元，粮票用尽）。(2) 可互换时总资源折合 $$60+30=90$$，有效价格大米 $3$、油 $2$，预算 $$3x_{1}+2x_{2}=90$$。由 $$MRS=\frac{x_{2}}{x_{1}+10}=\frac{3}{2}\Rightarrow x_{2}=\frac32x_{1}+15$$，代入得 $6x_{1}=60\Rightarrow x_{1}=10,\ x_{2}=30$，$U=600$。此时需货币 $20+30=50$、粮票 $10+30=40$，而原持有货币 60、粮票 30，故应把 10 元货币换成 10 元粮票。`,
      src: '2013 年北大光华 431 真题' },
    cu08: [{ q: R`效用 $U=XY$，求边际替代率 $MRS$`,
      a: R`$$MRS=\frac{MU_{X}}{MU_{Y}}=\frac{Y}{X}$$` },
    { q: R`（2017 真题）消费者效用 $U(b,c)=b^{0.5}c^{0.5}$，初始禀赋 2 公斤牛肉、3 公斤胡萝卜，可在市场出售禀赋。求禀赋点的边际替代率 $MRS_{bc}$，并说明存在何种价格比使她愿意直接消费自己的禀赋。`,
      a: R`$$MRS_{bc}=\frac{MU_{b}}{MU_{c}}=\frac{0.5b^{-0.5}c^{0.5}}{0.5b^{0.5}c^{-0.5}}=\frac{c}{b}$$ 禀赋点 $(b,c)=(2,3)$ 处 $$MRS=\frac{3}{2}$$ 直接消费禀赋最优要求 $MRS=\dfrac{p_{b}}{p_{c}}$，故取价格比 $\dfrac{p_{b}}{p_{c}}=\dfrac32$ 即可。`,
      src: '2017 北大光华 431 真题' } ],
    cu10: { q: R`已知某消费者效用函数 $U=XY$，收入 $I=100$，商品价格 $P_{X}=1,\ P_{Y}=4$。求最优消费组合，并验证此时 $MRS_{XY}=P_{X}/P_{Y}$。`,
      a: R`由 $$MRS_{XY}=\frac{MU_{X}}{MU_{Y}}=\frac{Y}{X}=\frac{P_{X}}{P_{Y}}=\frac14$$ 得 $Y=X/4$。代入预算约束 $$X+4Y=100$$ 得 $$X+4\cdot\frac{X}{4}=100\Rightarrow 2X=100\Rightarrow X=50,\ Y=12.5$$。验证：$$\frac{MU_{X}}{MU_{Y}}=\frac{12.5}{50}=\frac14=\frac{P_{X}}{P_{Y}}$$ 成立。`,
      a2: R`💡 巧解（柯布-道格拉斯公式）：$U=X^{1}Y^{1}$ 是 $a=b=1$ 的 CD 效用，直接套公式 $$X^{*}=\frac{a}{a+b}\cdot\frac{I}{P_X}=\frac{100}{2\times1}=50,\qquad Y^{*}=\frac{b}{a+b}\cdot\frac{I}{P_Y}=\frac{100}{2\times4}=12.5$$ 一步得解，无需列 MRS。`,
      src: '2006 年北京大学经济学真题（改编）' },
    cu11: [{ q: R`市场需求 $P=20-Q$，市场均衡价格 $P=8$。(1) 求均衡购买量；(2) 求消费者剩余 $CS$；(3) 若价格升至 $P=12$，消费者剩余变化多少？`,
      a: R`(1) $$8=20-Q\Rightarrow Q=12$$ (2) $$CS=\int_{0}^{12}(20-Q)\,dQ-8\times12=\left[20Q-\frac{Q^{2}}{2}\right]_{0}^{12}-96=(240-72)-96=72$$ (3) 当 $P=12$ 时 $Q=8$，$$CS'=\frac12(20-12)\times8=32$$ 消费者剩余减少 $72-32=40$。` },
    { q: R`（2024 真题）4 个同质厂商古诺竞争（边际成本 10），代表性消费者购买 $x$ 单位的效用为 $20x-5x^{2}$（逆需求 $P=20-10Q$）。古诺均衡总产量 $Q=\frac45$、价格 $P=12$；合谋时 $Q=\frac12,\ P=15$。分别求两种情形下的消费者剩余。`,
      a: R`古诺：$$CS_C=\int_{0}^{4/5}(20-10x)\,dx-12\times\frac45=\left[20x-5x^{2}\right]_{0}^{4/5}-9.6=12.8-9.6=3.2$$ 合谋：$$CS_M=\int_{0}^{1/2}(20-10x)\,dx-15\times\frac12=8.75-7.5=1.25$$ 合谋限产提价使消费者剩余减少 $3.2-1.25=1.95$。`,
      src: '2024 北大光华 431 真题' } ],
    cu14: [{ q: R`某消费者采购加湿器 $x$ 与净化器 $y$，效用 $U=x^{1/3}y^{2/3}$，加湿器价格 $P_{x}=1$、净化器价格 $P_{y}=4$，总预算 $M=24$。求两种商品的采购数量。`,
      a: R`由柯布-道格拉斯需求公式 $x^{*}=\dfrac{a}{a+b}\cdot\dfrac{M}{P_{x}}=\dfrac{1}{3}\cdot\dfrac{24}{1}=8$，$y^{*}=\dfrac{b}{a+b}\cdot\dfrac{M}{P_{y}}=\dfrac{2}{3}\cdot\dfrac{24}{4}=4$。故采购加湿器 $x=8$、净化器 $y=4$。`,
      a2: R`💡 巧解（边际替代率法，不背公式）：$MRS_{xy}=\dfrac{MU_x}{MU_y}=\dfrac{\tfrac13 x^{-2/3}y^{2/3}}{\tfrac23 x^{1/3}y^{-1/3}}=\dfrac{y}{2x}$，令 $=\dfrac{P_x}{P_y}=\dfrac14\Rightarrow x=2y$；代入预算 $x+4y=24\Rightarrow 2y+4y=24\Rightarrow y=4,\ x=8$。`,
      src: '2022 北大光华 431 真题' },
    { q: R`甜品店做月饼：五仁（$x_1$）与鲜肉（$x_2$）。消费者对两种盒装支付意愿相等：$4$ 个五仁 $+2$ 个鲜肉，与 $2$ 个五仁 $+4$ 个鲜肉。效用函数 $U=x_1^{\alpha}x_2^{1-\alpha}$（$0<\alpha<1$）。若改卖"$5$ 个五仁 $+$ 送 $1$ 个鲜肉"或"$5$ 个鲜肉 $+$ 送 $1$ 个五仁"的 5 个装，消费者对一盒 5 个月饼的支付意愿会提高吗？`,
      a: R`由 $(4,2)\sim(2,4)$：$$4^{\alpha}2^{1-\alpha}=2^{\alpha}4^{1-\alpha}\Rightarrow 2^{\alpha}=2^{1-\alpha}\Rightarrow\alpha=\tfrac12$$ 故 $U=x_1^{1/2}x_2^{1/2}=\sqrt{x_1x_2}$。原盒 $(4,2)$ 效用 $\sqrt8=2\sqrt2$；新盒 $(5,1)$ 效用 $\sqrt5\approx2.24<2.83$。故新营销的 5+1 组合效用低于原 4+2 组合，支付意愿**不会提高**（柯布-道格拉斯偏好"均衡搭配"，偏离均衡组合效用下降）。`,
      src: '2019 北大光华 431 真题' } ],
    cu16: [{ q: R`完全互补品 $U=\min\{X,Y\}$，均衡时 $X$ 与 $Y$ 的关系`,
      a: R`均衡时 $X=Y$（按固定比例消费）。` },
    { q: R`（2017 真题）消费者效用 $U(b,c)=\min\{b,c\}$（完全互补），初始禀赋 2 公斤薯片、3 升饮料，可在市场出售禀赋。是否存在一组市场价格使他愿意直接消费自己的禀赋？`,
      a: R`完全互补品最优消费必满足 $b=c$（固定比例 1:1）。禀赋点 $(b,c)=(2,3)$ 处 $b\neq c$，故对任何正价格他都不会直接消费禀赋——他会卖出 1 升饮料换薯片，直到 $b=c$。`,
      src: '2017 北大光华 431 真题' } ],
    cu24: { q: R`写出效用最大化问题 $U=XY$ 在 $P_{X}X+P_{Y}Y=I$ 下的拉格朗日函数`,
      a: R`$$\mathcal{L}=XY+\lambda(I-P_{X}X-P_{Y}Y)$$` },
    el01: { q: R`需求函数的一般形式`,
      a: R`$$Q^{d}=f(P)$$（通常负相关）` },
    el02: { q: R`供给函数的一般形式`,
      a: R`$$Q^{s}=f(P)$$（通常正相关）` },
    el03: { q: R`某商品市场需求 $Q^{d}=100-2P$，市场供给 $Q^{s}=20+2P$。(1) 求均衡价格与均衡数量；(2) 若政府对每单位商品征收 4 元从量税（由供给者缴纳），求新的均衡价与数量，并指出税负在买卖双方间的分担；(3) 若改为对生产者每单位补贴 4 元，求新的均衡价与数量。`,
      a: R`(1) $$100-2P=20+2P\Rightarrow P=20,\ Q=60$$ (2) 征税后供给曲线 $$Q^{s}=20+2(P-4)=12+2P$$，令 $$100-2P=12+2P\Rightarrow P=22,\ Q=56$$。消费者支付 $22$（多付 $2$），生产者实得 $22-4=18$（少得 $2$），各承担一半税负。(3) 补贴后供给曲线 $$Q^{s}=20+2(P+4)=28+2P$$，令 $$100-2P=28+2P\Rightarrow P=18,\ Q=64$$。消费者少付 $2$ 元，生产者实得 $18+4=22$（多 $2$ 元）。`,
      a2: R`💡 巧解（税负对称性）：需求斜率 $-2$ 与供给斜率 $+2$ 绝对值相等，故税负必然各半。征税 $t=4$：消费者支付 $P_c=20+2=22$、生产者实得 $P_s=20-2=18$，无需重解方程；数量由任一曲线 $Q^d(22)=100-44=56$ 直接读出。补贴同理反向：$P_c=18,\ P_s=22,\ Q=64$。`,
      src: '2014 年北京交通大学 820 真题（改编）' },
    el04: { q: R`需求函数 $Q=100-2P$。(1) 求 $P=25$ 时的需求价格点弹性；(2) 判断该点是否富有弹性，并说明降价对总收益的影响；(3) 若厂商降价 $1\%$，需求量大约变化百分之几？`,
      a: R`(1) 当 $P=25$ 时 $Q=50$，$$\varepsilon_{d}=\frac{dQ}{dP}\cdot\frac{P}{Q}=-2\cdot\frac{25}{50}=-1,\quad |\varepsilon_{d}|=1$$ (2) 单位弹性，降价不改变总收益。(3) $|\varepsilon_{d}|=1$，降价 $1\%$ 使需求量增加约 $1\%$。`,
      a2: R`💡 巧解（截距法）：线性需求 $Q=100-2P=2(50-P)$，截距价（需求量为零时的价格）$a=50$。点弹性 $$|\varepsilon_{d}|=\frac{P}{a-P}=\frac{25}{50-25}=1$$ 一步得单位弹性，免去求导代入。`,
      src: '2017 年中央财经大学 801 真题（改编）' },
    el05: { q: R`某商品价格由 $P_{1}=2$ 元上涨至 $P_{2}=4$ 元，需求量由 $Q_{1}=10$ 件降至 $Q_{2}=6$ 件。(1) 用中点公式求需求价格弧弹性；(2) 判断该商品在此区间是否富有弹性。`,
      a: R`(1) $$|\varepsilon_{d}|=\left|\frac{Q_{2}-Q_{1}}{(Q_{1}+Q_{2})/2}\div\frac{P_{2}-P_{1}}{(P_{1}+P_{2})/2}\right|=\left|\frac{6-10}{8}\div\frac{4-2}{3}\right|=\frac{0.5}{2/3}=0.75$$ (2) $|\varepsilon_{d}|=0.75<1$，缺乏弹性。` },
    el06: { q: R`消费者收入由 $1000$ 元增至 $1200$ 元，其对某商品的需求量由 $20$ 件增至 $26$ 件。(1) 用中点公式求需求收入弹性；(2) 判断该商品属于正常品还是低档品，以及是必需品还是奢侈品。`,
      a: R`(1) $$\varepsilon_{I}=\frac{(26-20)/((20+26)/2)}{(1200-1000)/((1000+1200)/2)}=\frac{6/23}{200/1100}=\frac{33}{23}\approx1.43$$ (2) $\varepsilon_{I}=1.43>0$，为正常品；且 $\varepsilon_{I}>1$，为奢侈品。` },
    el07: { q: R`商品 $Y$ 的价格上升 $10\%$，商品 $X$ 的需求量增加 $8\%$。(1) 求 $X$ 对 $Y$ 的交叉价格弹性；(2) 判断 $X$ 与 $Y$ 之间的关系。`,
      a: R`(1) $$\varepsilon_{XY}=\frac{\Delta Q_{X}/Q_{X}}{\Delta P_{Y}/P_{Y}}=\frac{8\%}{10\%}=0.8$$ (2) $\varepsilon_{XY}=0.8>0$，$X$ 与 $Y$ 为替代品（$Y$ 涨价使消费者转向购买 $X$）。` },
    el13: { q: R`需求富有弹性（$|\varepsilon_{d}|>1$）时，降价对总收益的影响`,
      a: R`总收益增加。` },
    el14: [{ q: R`设 $P=10,\ |\varepsilon_{d}|=5$，求边际收益 $MR$`,
      a: R`$$MR=P\left(1-\frac{1}{|\varepsilon|}\right)=10\left(1-\frac15\right)=8$$` },
    { q: R`（2014 真题）垄断厂商需求 $Q=144/P^2$（即 $P=12Q^{-1/2}$）。用 $MR=P\left(1-\frac{1}{|\varepsilon|}\right)$ 求其边际收益函数。`,
      a: R`$Q=144P^{-2}$ 的需求价格弹性恒为 $|\varepsilon|=2$，故 $$MR=P\left(1-\frac12\right)=\frac{P}{2}=6Q^{-1/2}$$ 恒弹性需求下边际收益恰为价格的一半。`,
      src: '2014 北大光华 431 真题' } ],
    cu29: { q: R`消费者效用 $U=XY$，收入 $m=100$，$P_{Y}=1$ 不变，$P_{X}$ 由 2 降至 1。求：(1) 价格下降对 $X$ 的总效应；(2) 按斯勒茨基法分解为替代效应与收入效应。`,
      a: R`(1) 马歇尔需求 $$X=\frac{m}{2P_{X}}$$。$P_{X}=2$ 时 $X_{0}=\frac{100}{4}=25$；$P_{X}=1$ 时 $X_{1}=\frac{100}{2}=50$，故总效应 $$=50-25=25$$。(2) 原消费束 $(25,50)$ 在新价格下成本为 $$1\times25+1\times50=75$$，为维持原购买力需补偿到 $m'=75$。补偿需求 $$X^{s}=\frac{75}{2\times1}=37.5$$，故替代效应 $$=37.5-25=12.5$$，收入效应 $$=50-37.5=12.5$$。验证：总效应 $=12.5+12.5=25$。`,
      a2: R`💡 巧解（对偶·希克斯分解）：$U=XY$ 的希克斯需求为 $h_X=U^{1/2}\Big(\dfrac{P_Y}{P_X}\Big)^{1/2}$。原效用 $U_0=25\times50=1250$，在 $P_X=1$ 处 $h_X=\sqrt{1250}\approx35.36$。故希克斯替代效应 $=35.36-25=10.36$，收入效应 $=50-35.36=14.64$（总效应仍 $25$）。注意希克斯与斯勒茨基分解数值不同（$10.36/14.64$ vs $12.5/12.5$），做题时看清题目要求哪种分解。`,
      src: '2014 年上海交通大学 841 真题（改编）' },
    cu30: [{ q: R`补偿变化 CV 衡量的是什么？`,
      a: R`价格变动后，为维持原效用水平所需补偿（或抽取）的收入额。` },
    { q: R`（2016 真题）甲、乙效用均为 $U=X_{1}^{0.5}X_{2}^{0.5}$，$P_{1}=10,\ P_{2}=1$，收入 $I=100$。乙有馅饼半价券（券后 $P_{1}=5$，只能用一次），持券时 $U=10\sqrt{5}$。乙出让该券至少应得多少钱（即补偿变化 CV）？`,
      a: R`出让券后乙的价格回到 $P_{1}=10$。为维持原效用 $10\sqrt5$ 所需收入 $m'$ 满足 $$V(10,1,m')=\frac{m'}{2\sqrt{10}}=10\sqrt5\Rightarrow m'=100\sqrt2\approx141.42$$ 故 $$CV=m'-I=100\sqrt2-100\approx41.42$$ 即价格变动（失去优惠）后为维持原效用水平所需补偿的收入额。`,
      src: '2016 北大光华 431 真题' } ],
    un01: [{ q: R`某彩票以概率 $0.5$ 得 100 元、$0.5$ 得 0 元，效用 $u=\sqrt{x}$，求期望效用`,
      a: R`$$EU=0.5\sqrt{100}+0.5\sqrt{0}=5$$` },
    { q: R`（2017 真题）农民有 $10000$ 元，买水稻种子 $s$（$p=1$ 元/公斤）与保险 $i$（$q=2$ 元/份，每份赔付 1 公斤大米）。天气好（概率 $0.8$）消费 $C_{1}=10\sqrt{s}$，天气不好（$0.2$）消费 $C_{2}=i$。写出期望效用并求最优 $s,i$。`,
      a: R`期望效用 $$EU=0.8\log(10\sqrt{s})+0.2\log i$$ 预算 $s+2i=10000$。一阶条件 $\frac{0.4}{s}=\frac{0.1}{i}\Rightarrow s=4i$，代入预算得 $$i=\frac{5000}{3}\approx1667,\qquad s=\frac{20000}{3}\approx6667$$ 期望效用最大化即按状态概率加权平均各状态效用。`,
      src: '2017 北大光华 431 真题' } ],
    un05: { q: R`小明效用函数 $U(W)=60W-W^{2}$（$0\le W\le30$），初始财富 $W_{0}=20$。有一张彩票：以 50% 概率得 10 元、50% 概率得 0 元。(1) 若小明已持有该彩票，他愿出售的最低价格是多少？(2) 若小明未持有，他愿购买的最高价格是多少？(3) 初始财富 $W_{0}$ 下降时，出售价格如何变化？`,
      a: R`持有彩票的期望效用 $EU=0.5\,u(30)+0.5\,u(20)=0.5\times900+0.5\times800=850$；$u''(W)=-2<0$，风险厌恶。(1) 出售价 $p$ 使 $u(20+p)=850$，即 $60(20+p)-(20+p)^{2}=850\Rightarrow p^{2}-20p+50=0$，取 $p=10-5\sqrt{2}\approx2.93$（另一根超出定义域）。确定性等价 $CE=20+p=30-5\sqrt{2}\approx22.93$，风险溢价 $E(W)-CE=25-22.93\approx2.07$。(2) 购买价 $p_{b}$ 使 $0.5\,u(30-p_{b})+0.5\,u(20-p_{b})=u(20)=800$。令 $a=20-p_{b}$，得 $a^{2}-50a+550=0$，取 $a=25-5\sqrt{3}\approx16.34$，故 $p_{b}=20-a=5\sqrt{3}-5\approx3.66$。(3) 一般地 $CE$ 满足 $60CE-CE^{2}=50W_{0}+250-W_{0}^{2}$，两边对 $W_{0}$ 求导得 $\dfrac{dCE}{dW_{0}}=\dfrac{50-2W_{0}}{60-2CE}<1$，故 $\dfrac{dp}{dW_{0}}=\dfrac{dCE}{dW_{0}}-1<0$：$W_{0}$ 下降时出售价上升（财富越低边际效用越高、绝对风险厌恶 $\dfrac{2}{60-2W}$ 越大）。`,
      src: '2026 北大光华 431 真题' },
    un06: [{ q: R`期望值 $E(x)=50$，确定性等价 $CE=25$，求风险溢价`,
      a: R`$$RP=E(x)-CE=50-25=25$$` },
    { q: R`（2015 真题）某人资产 $250000$ 元，拿出 $200000$ 元买车（事故概率 $5\%$，出事后车值降为 $40000$ 元），效用 $U(W)=W^{1/2}$。求期望财富、确定性等价与风险溢价。`,
      a: R`期望财富 $$E(W)=0.95\times250000+0.05\times90000=242000$$ 期望效用 $EU=0.95\times500+0.05\times300=490$，确定性等价 $\sqrt{CE}=490\Rightarrow CE=240100$。风险溢价 $$RP=E(W)-CE=242000-240100=1900$$ 即愿比公平保费多付 $1900$ 元以消除风险。`,
      src: '2015 北大光华 431 真题' } ],
    mk03: { q: R`完全竞争市场中，某代表性厂商短期成本 $STC=Q^{3}-3Q^{2}+6Q+50$，市场价格 $P=6$。(1) 求短期均衡产量；(2) 求此时的利润；(3) 判断厂商短期是否应继续生产。`,
      a: R`(1) $$MC=\frac{dSTC}{dQ}=3Q^{2}-6Q+6$$ 令 $P=MC$：$$3Q^{2}-6Q+6=6\Rightarrow 3Q(Q-2)=0$$ 取 $Q=2$（$Q=0$ 处 $MC$ 递减，非利润最大化点）。(2) $$TR=6\times2=12,\quad TC=8-12+12+50=58,\quad \pi=12-58=-46$$ (3) $$AVC=\frac{Q^{3}-3Q^{2}+6Q}{Q}=Q^{2}-3Q+6$$ 令 $\frac{dAVC}{dQ}=2Q-3=0$ 得 $Q=1.5$，$AVC_{\min}=2.25-4.5+6=3.75$。因 $P=6>AVC_{\min}=3.75$，虽亏损 $46$ 元（固定成本 $50$ 无法全部收回），但继续生产可弥补全部可变成本并部分弥补固定成本，故短期继续生产。` },
    mk04: { q: R`完全竞争长期均衡时厂商的经济利润`,
      a: R`为零（$P=MC=AC_{\min}$）。` },
    rv08: [{ q: R`完全竞争下 $P=15$，求边际收益 $MR$`,
      a: R`$$MR=P=15$$` },
    { q: R`（2016 真题）完全竞争钢铁市场：需求 $Q^{d}=20-P$、供给（反函数）$P^{s}=2+Q$，市场均衡价格 $P=11$。完全竞争厂商的边际收益为多少？`,
      a: R`市场均衡：$20-Q=2+Q\Rightarrow Q=9,\ P=11$。完全竞争厂商是价格接受者、面临水平需求线，$$MR=P=11$$ 每多卖一单位均按市场价格 $11$ 出售，边际收益等于价格。`,
      src: '2016 北大光华 431 真题' } ],
    rv11: { q: R`$P=8,\ AVC_{\min}=5$，厂商短期应继续生产吗？`,
      a: R`$P>AVC$，继续生产。` },
    rv13: { q: R`完全竞争长期均衡时 $P$ 与 $AC$ 的关系`,
      a: R`$$P=AC_{\min}$$（经济利润为零）` },
    mk06: [{ q: R`某山道小贩独家出售一种工艺品，面临市场需求 $P=100-Q$，无固定成本，边际成本 $MC=5$。(1) 求垄断最优产量与定价、利润；(2) 求完全竞争（$P=MC$）下的产量与价格；(3) 计算垄断造成的无谓损失。`,
      a: R`(1) $$TR=100Q-Q^{2},\quad MR=100-2Q$$ 令 $MR=MC$：$$100-2Q=5\Rightarrow Q=47.5,\ P=52.5$$ $$\pi=(52.5-5)\times47.5=2256.25$$ (2) 竞争下 $$P=MC\Rightarrow 100-Q=5\Rightarrow Q=95,\ P=5$$。(3) $$DWL=\frac12(52.5-5)(95-47.5)=\frac12\times47.5\times47.5=1128.125$$`,
      a2: R`💡 巧解（线性垄断中点公式）：$P=a-bQ=100-Q$、常数 $MC=c=5$ 时，垄断产量与价格是「需求截距与 $MC$ 的中点」：$$Q_M=\frac{a-c}{2b}=\frac{95}{2}=47.5,\qquad P_M=\frac{a+c}{2}=\frac{105}{2}=52.5$$ 竞争产量 $Q_C=\dfrac{a-c}{b}=95$；无谓损失公式 $$DWL=\frac{(a-c)^{2}}{8b}=\frac{95^{2}}{8}=1128.125$$ 免去逐段推导。`,
      src: '2013 年北大光华 431 真题（改编）' },
    { q: R`垄断厂商需求 $Q=144/P^2$（即 $P=12Q^{-1/2}$），$AVC=Q^{1/2}$，固定成本 $F=5$。(1) 求利润最大化的价格、产量与利润；(2) 政府规定价格不得高于 $4$，最优产量与利润；(3) 政府想让厂商在尽可能高产量下生产，最高限价应为多少？`,
      a: R`(1) $TR=PQ=12Q^{1/2}$，$MR=6Q^{-1/2}$；$VC=Q^{3/2}$，$MC=\tfrac32 Q^{1/2}$。$MR=MC$：$$6Q^{-1/2}=\tfrac32 Q^{1/2}\Rightarrow Q=4,\ P=12/\sqrt4=6$$ $$\pi=12\sqrt4-4^{3/2}-5=24-8-5=11$$ (2) 限价 $P=4$ 下厂商按 $MC=P$ 生产：$$\tfrac32 Q^{1/2}=4\Rightarrow Q=64/9$$ $$\pi=4\cdot\tfrac{64}{9}-\left(\tfrac{64}{9}\right)^{3/2}-5=\tfrac{121}{27}\approx4.48$$ (3) 最高限价取边际成本定价 $P=MC$（需求与 $MC$ 交点处产量最大）：$$12Q^{-1/2}=\tfrac32 Q^{1/2}\Rightarrow Q=8,\ \bar P=12/\sqrt8=3\sqrt2\approx4.24$$ 此时 $\pi=8\sqrt2-5\approx6.31>0$，厂商仍愿生产且产量达最大。`,
      a2: R`💡 巧解（恒弹性加成）：$Q=144P^{-2}$ 的需求价格弹性恒为 $|\varepsilon|=2$，垄断定价直接由加成公式 $$P=\frac{MC}{1-\frac{1}{|\varepsilon|}}=2MC=2\cdot\tfrac32 Q^{1/2}=3Q^{1/2}$$ 与反需求 $P=12Q^{-1/2}$ 联立：$$3Q^{1/2}=12Q^{-1/2}\Rightarrow Q=4,\ P=6$$ 免去求 $MR$ 的步骤。`,
      src: '2014 北大光华 431 真题' } ],
    mk07: [{ q: R`$MC=10,\ |\varepsilon|=2$，求垄断定价`,
      a: R`$$P=\frac{MC}{1-1/|\varepsilon|}=\frac{10}{1-1/2}=20$$` },
    { q: R`（2014 真题）垄断厂商需求 $Q=144/P^2$（恒弹性 $|\varepsilon|=2$），$AVC=Q^{1/2}$（故 $MC=\frac32 Q^{1/2}$）。用加成定价公式求最优价格与产量。`,
      a: R`加成公式 $$P=\frac{MC}{1-\frac{1}{|\varepsilon|}}=\frac{\frac32 Q^{1/2}}{1-\frac12}=3Q^{1/2}$$ 与反需求 $P=12Q^{-1/2}$ 联立：$$3Q^{1/2}=12Q^{-1/2}\Rightarrow Q=4,\qquad P=6$$ 垄断者总在需求富有弹性段（$|\varepsilon|=2>1$）定价。`,
      src: '2014 北大光华 431 真题' } ],
    mk08: { q: R`某垄断厂商定价 $P=10$，边际成本 $MC=6$。(1) 求勒纳指数 $L$；(2) 由 $L=1/|\varepsilon|$ 反推其需求价格弹性的绝对值。`,
      a: R`(1) $$L=\frac{P-MC}{P}=\frac{10-6}{10}=0.4$$ (2) 由 $$L=\frac{1}{|\varepsilon|}$$ 得 $$|\varepsilon|=\frac{1}{0.4}=2.5$$。`,
      src: '2006 年北京大学经济学真题（改编）' },
    mk09: [{ q: R`垄断造成无谓损失的原因`,
      a: R`垄断产量低于竞争产量、价格高于边际成本。` },
    { q: R`（2014 真题）垄断厂商需求 $Q=144/P^2$（$P=12Q^{-1/2}$），$MC=\frac32 Q^{1/2}$。垄断均衡产量 $Q=4$、价格 $P=6$；边际成本定价（$P=MC$）时产量 $Q=8$。说明垄断为何造成无谓损失。`,
      a: R`垄断者按 $MR=MC$ 生产 $Q=4<8$（竞争/边际成本定价产量），价格 $P=6>MC=3$。产量低于竞争水平、价格高于边际成本，使 $Q\in(4,8)$ 区间内本可互利的交易被放弃，造成无谓损失。`,
      src: '2014 北大光华 431 真题' } ],
    rv09: { q: R`垄断需求 $P=100-Q$，求边际收益 $MR$`,
      a: R`$$MR=100-2Q$$` },
    mk10: { q: R`三级价格歧视下，弹性较小市场的定价`,
      a: R`定价较高（弹性越小加价越高）。` },
    gm04: { q: R`王刚与李红合作完成小组作业，通过则每人效用 $3$，不通过为 $0$。二人各选努力水平：不努力 $N$（成本 0）、低努力 $l$（成本：王刚 2、李红 1）、高努力 $h$（成本：王刚 4、李红 3）。小组通过当且仅当两人都选 $l$ 或至少一人选 $h$。写出支付矩阵并求全部纳什均衡。`,
      a: R`支付矩阵（行：王刚；列：李红，先王刚后李红）：$$(N,N)=(0,0),\ (N,l)=(0,-1),\ (N,h)=(3,0)$$ $$(l,N)=(-2,0),\ (l,l)=(1,2),\ (l,h)=(1,0)$$ $$(h,N)=(-1,3),\ (h,l)=(-1,2),\ (h,h)=(-1,0)$$ 逐格检查单方面偏离，得纯策略纳什均衡为 $(N,N)$、$(N,h)$ 与 $(l,l)$（在 $(N,N)$、$(N,h)$ 处李红在 $N$ 与 $h$ 间无差异，属弱纳什均衡）。`,
      src: '2013 年北大光华 431 真题' },
    gm05: { q: R`囚徒困境的均衡结果`,
      a: R`两人都招供（个体理性导致集体非理性）。` },
    mk18: [{ q: R`双寡头古诺竞争，市场需求 $P=100-Q$，两厂商边际成本均为 0。(1) 写出厂商 1 的反应函数；(2) 求古诺均衡产量与价格。`,
      a: R`(1) 厂商 1 利润 $$\pi_{1}=(100-q_{1}-q_{2})q_{1}$$，令 $$\frac{\partial\pi_{1}}{\partial q_{1}}=100-2q_{1}-q_{2}=0\Rightarrow q_{1}=\frac{100-q_{2}}{2}$$。(2) 对称均衡 $q_{1}=q_{2}=q$：$$q=\frac{100-q}{2}\Rightarrow q=\frac{100}{3}$$，总产量 $$Q=\frac{200}{3}$$，价格 $$P=100-\frac{200}{3}=\frac{100}{3}$$。`,
      a2: R`💡 巧解（对称古诺公式）：对称古诺直接套 $$q_1=q_2=\frac{a-c}{3b}=\frac{100-0}{3}=\frac{100}{3},\qquad Q=\frac{2(a-c)}{3b}=\frac{200}{3},\qquad P=\frac{a+2c}{3}=\frac{100}{3}$$ 无需推导反应函数。`,
      src: '2006 年北京大学经济学真题（改编）' },
    { q: R`双寡头，需求 $P=9-q_1-q_2$，边际成本 $C_1=C_2=3$。(1) 古诺模型求均衡产量；(2) 企业 1 可一次性投入 $f=11$ 研发使 $C_1=0$（不投入则仍为 3），企业 2 观察到企业 1 是否研发后再同时定产，求纯策略子博弈精炼均衡；(3) 若企业 1 是否研发与两企业产量选择**同时**决策（企业 2 定产时观察不到研发），求纯策略纳什均衡。`,
      a: R`(1) 古诺 $q_1=q_2=\frac{9-3}{3}=2$，$\pi_1=\pi_2=(9-4-3)\times2=4$。(2) 序贯：投入研发后 $C_1=0$，古诺得 $q_1=\frac{9-0+3}{3}=4,\ q_2=\frac{9-2\cdot3+0}{3}=1$，$\pi_1=16-11=5>4$、$\pi_2=(4-3)\times1=1$；不投入则回到 (1)。故企业 1 选择投入，SPE：企业 1 研发（$C_1=0$）、$q_1=4,q_2=1$，利润 $(5,1)$。(3) 同时决策下企业 2 观察不到研发、仍按 $q_2=2$ 反应；若企业 1 研发，其最优 $q_1=\frac{9-2}{2}=3.5$，$\pi_1=3.5^2-11=1.25<4$，故不研发。纯策略纳什均衡：企业 1 不研发，$q_1=q_2=2$，$\pi_1=\pi_2=4$——研发的战略价值依赖于对手可观察（承诺/可置信性）。`,
      src: '2023 北大光华 431 真题' } ],
    mk20: [{ q: R`斯塔克伯格双寡头，市场需求 $P=100-Q$，两厂商边际成本均为 0，厂商 1 为产量领导者。求领导者与追随者的均衡产量。`,
      a: R`先求追随者反应函数：$$q_{2}=\frac{100-q_{1}}{2}$$。领导者利润 $$\pi_{1}=(100-q_{1}-q_{2})q_{1}=\Big(100-q_{1}-\frac{100-q_{1}}{2}\Big)q_{1}=\Big(50-\frac{q_{1}}{2}\Big)q_{1}$$，令 $$\frac{d\pi_{1}}{dq_{1}}=50-q_{1}=0\Rightarrow q_{1}=50$$，故 $$q_{2}=\frac{100-50}{2}=25$$。`,
      a2: R`💡 巧解（斯塔克伯格公式）：对称产量领导直接套 $$q_L=\frac{a-c}{2b}=\frac{100}{2}=50,\qquad q_F=\frac{a-c}{4b}=\frac{100}{4}=25$$ 领导者产量恰为垄断量、追随者为其一半，免去逐步反向归纳。`,
      src: '2017 年中央财经大学 801 真题（改编）' },
    { q: R`双寡头，需求 $P(q_1,q_2)=1-q_1-q_2$，生产成本为 0，决策变量为产量。(1) 斯塔克伯格模型（企业 1 领导、企业 2 追随）求均衡 $q_1^*,q_2^*$；(2) 古诺模型中企业 1 聘职业经理人，工资与产量挂钩，目标函数变为 $\pi_1+\eta q_1-w=(1-q_1-q_2)q_1+\eta q_1-w$（$\eta,w$ 公共知识），求两企业均衡产量（表为 $\eta$ 的函数）。`,
      a: R`(1) 追随者反应函数 $q_2=\frac{1-q_1}{2}$；领导者最大化 $\left(1-q_1-\frac{1-q_1}{2}\right)q_1=\frac{1-q_1}{2}q_1$，一阶条件 $\frac{1-2q_1}{2}=0\Rightarrow q_1^*=\frac12$，故 $q_2^*=\frac14$。(2) 企业 1 一阶条件 $1-2q_1-q_2+\eta=0\Rightarrow q_1=\frac{1+\eta-q_2}{2}$；企业 2 仍为 $q_2=\frac{1-q_1}{2}$。联立解得 $$q_1^*=\frac{1+2\eta}{3},\qquad q_2^*=\frac{1-\eta}{3}$$ 经理人激励 $\eta$ 使企业 1 的"边际收益"上移、产量更激进（抢占市场），$\eta$ 越大 $q_1$ 越大、$q_2$ 越小。`,
      src: '2023 北大光华 431 真题' } ],
    mk21: { q: R`伯特兰同质产品价格竞争的均衡价格`,
      a: R`$$P=MC$$` },
    wf02: { q: R`帕累托最优的含义`,
      a: R`不存在使任何人变好而不使他人变坏的改进。` },
    wf11: [{ q: R`社会总剩余的构成`,
      a: R`总剩余 = 消费者剩余 + 生产者剩余。` },
    { q: R`（2024 真题）4 厂商古诺（$MC=10$）：均衡 $P=12$、每家产量 $0.2$、消费者剩余 $3.2$；合谋：$P=15$、$Q=0.5$、消费者剩余 $1.25$。分别求两种情形的社会总剩余，并说明为何合谋的总剩余更小。`,
      a: R`古诺：生产者剩余 $=4\times(12-10)\times0.2=1.6$，总剩余 $=3.2+1.6=4.8$。合谋：生产者剩余 $=(15-10)\times0.5=2.5$，总剩余 $=1.25+2.5=3.75$。总剩余 $=$ 消费者剩余 $+$ 生产者剩余；合谋限产提价虽增加生产者剩余，但消费者剩余减少更多，总剩余下降 $4.8-3.75=1.05$（无谓损失）。`,
      src: '2024 北大光华 431 真题' } ],
    pd05: { q: R`当 $MP>AP$ 时，平均产量 $AP$ 如何变化？`,
      a: R`$AP$ 上升（$MP$ 曲线从上方穿过 $AP$ 最高点）。` },
    pd06: { q: R`等产量线的特征`,
      a: R`向右下方倾斜、凸向原点、互不相交，离原点越远产量越高。` },
    pd08: { q: R`边际技术替代率递减的原因`,
      a: R`要素边际报酬递减（等产量线凸向原点）。` },
    pd14: { q: R`理性厂商应在生产的哪个阶段组织生产？`,
      a: R`第Ⅱ阶段（$AP$ 递减但 $MP$ 为正）。` },
    pd16: [{ q: R`固定比例生产 $Q=\min\{L,K\}$，生产 $Q=4$ 的要素组合`,
      a: R`$$L=K=4$$` },
    { q: R`（2015 真题）生产函数 $f(x_{1},x_{2})=\min\{x_{1},\,x_{2}^{\alpha}\}$（$\alpha>0$），要素价格 $w_{1}=10,\ w_{2}=20$。求成本函数。`,
      a: R`固定比例（里昂惕夫）型生产在有效生产点满足 $x_{1}=x_{2}^{\alpha}$。生产 $q$ 需投入 $$x_{1}=q,\qquad x_{2}=q^{1/\alpha}$$ 故成本函数 $$C(q)=w_{1}x_{1}+w_{2}x_{2}=10q+20q^{1/\alpha}$$ 由 $\min$ 型函数按固定比例确定要素需求、再代入要素价格得到。`,
      src: '2015 北大光华 431 真题' } ],
    pd17: { q: R`线性生产 $Q=L+2K$ 的等产量线形状`,
      a: R`直线（要素完全替代）。` },
    ct03: { q: R`设 $FC=100,\ Q=25$，求平均固定成本 $AFC$`,
      a: R`$$AFC=\frac{FC}{Q}=4$$` },
    ct04: { q: R`设 $VC=2Q$，求平均可变成本 $AVC$`,
      a: R`$$AVC=\frac{VC}{Q}=2$$` },
    ct07: { q: R`当 $MC=AVC$ 时，$AVC$ 处于什么状态？`,
      a: R`$AVC$ 取最小值（$MC$ 穿过 $AVC$ 最低点）。` },
    ct08: { q: R`设工资 $w=10$，$MP_{L}=5$，求边际成本 $MC$`,
      a: R`$$MC=\frac{w}{MP_{L}}=2$$` },
    ct09: { q: R`设 $w=10$，$AP_{L}=5$，求平均可变成本 $AVC$`,
      a: R`$$AVC=\frac{w}{AP_{L}}=2$$` },
    ct10: { q: R`长期平均成本 $LAC$ 与短期平均成本的关系`,
      a: R`$LAC$ 是各短期 $AC$ 的包络线（下包络）。` },
    ct11: { q: R`用 $S=\dfrac{AC}{MC}$ 判断：当 $S>1$ 时`,
      a: R`存在规模经济（$AC$ 随产量下降）。` },
    ct12: { q: R`范围经济 $SC>0$ 的含义`,
      a: R`联合生产比分别生产成本更低。` },
    ct13: { q: R`设 $w=2,\ L=Q^{2}$，固定成本 $r\bar{K}=10$，写出短期总成本`,
      a: R`$$STC=2Q^{2}+10$$` },
    ct16: { q: R`$TC=Q^{3}-2Q^{2}+5Q+20$，求 $FC$ 与 $VC$`,
      a: R`$$FC=20,\qquad VC=Q^{3}-2Q^{2}+5Q$$` },
    ct17: { q: R`设 $LTC=Q^{3}-4Q^{2}+10Q$，求长期边际成本 $LMC$`,
      a: R`$$LMC=\frac{dLTC}{dQ}=3Q^{2}-8Q+10$$` },
    pd15: { q: R`扩展线的含义`,
      a: R`各最优要素组合（$\frac{MP_{L}}{w}=\frac{MP_{K}}{r}$）的轨迹。` },
    pd21: { q: R`包络定理的内容`,
      a: R`目标函数最优值对参数的导数，等于拉格朗日函数对参数的偏导数。` },
    pd22: { q: R`规模报酬递增时，长期平均成本如何变化？`,
      a: R`$LAC$ 随产量增加而下降。` },
    pd19: { q: R`霍特林引理的内容`,
      a: R`$$y=\frac{\partial\pi}{\partial p},\qquad -L=\frac{\partial\pi}{\partial w}$$` },
    rv07: { q: R`利润最大化的二阶条件`,
      a: R`$$\frac{dMR}{dQ}<\frac{dMC}{dQ}$$` },
    rv10: { q: R`生产者剩余 $PS$ 的计算`,
      a: R`$$PS=TR-VC$$` },
    el08: { q: R`价格上升 5%，供给量增加 10%，求供给弹性`,
      a: R`$$\varepsilon_{s}=\frac{10\%}{5\%}=2$$` },
    el09: { q: R`$|\varepsilon_{d}|>1$ 称为`,
      a: R`富有弹性（需求对价格反应敏感）。` },
    el10: [{ q: R`需求 $Q=100-2P$，$P=10$，求 $|\varepsilon_{d}|$`,
      a: R`$Q=80$，$$|\varepsilon_{d}|=\left|-2\cdot\frac{10}{80}\right|=0.25$$` },
    { q: R`（2015 真题）北京市场卫星电视需求 $Q_{B}=60-0.25P_{B}$，均衡 $P_{B}=140,\ Q_{B}=25$。求该均衡点的需求价格点弹性。`,
      a: R`$$|\varepsilon_{d}|=\left|\frac{dQ}{dP}\cdot\frac{P}{Q}\right|=0.25\times\frac{140}{25}=1.4$$ 北京市场在均衡点需求富有弹性（$1.4>1$）。`,
      src: '2015 北大光华 431 真题' } ],
    el11: { q: R`收入弹性 $\varepsilon_{I}=2$ 的商品属于`,
      a: R`正常品中的奢侈品。` },
    el12: [{ q: R`交叉弹性 $\varepsilon_{XY}<0$ 时两商品关系`,
      a: R`互补品。` },
    { q: R`（2016 真题）垄断经营者同时销售两种产品，需求 $D_{1}(p_{1},p_{2})=3-\frac{p_{2}}{p_{1}^{2}}$、$D_{2}(p_{1},p_{2})=3-\frac{p_{1}}{p_{2}^{2}}$。判断两种产品是替代品还是互补品。`,
      a: R`$$\frac{\partial D_{1}}{\partial p_{2}}=-\frac{1}{p_{1}^{2}}<0,\qquad \frac{\partial D_{2}}{\partial p_{1}}=-\frac{1}{p_{2}^{2}}<0$$ 一种商品涨价使另一种商品需求下降，交叉影响为负，故两种产品为**互补品**（交叉价格弹性为负）。`,
      src: '2016 北大光华 431 真题' } ],
    el15: { q: R`蛛网模型价格波动收敛的条件`,
      a: R`$$|\varepsilon_{s}|<|\varepsilon_{d}|$$` },
    el16: { q: R`消费者收入增加使需求曲线如何移动？`,
      a: R`向右移动（正常品）。` },
    el17: { q: R`技术进步使供给曲线如何移动？`,
      a: R`向右移动。` },
    el18: { q: R`征税时，税负更多由谁承担？`,
      a: R`弹性较小（越缺乏弹性）的一方。` },
    cu37: [{ q: R`罗伊恒等式`,
      a: R`$$x_{i}=-\frac{\partial V/\partial p_{i}}{\partial V/\partial m}$$` },
    { q: R`（2016 真题）效用 $U=X_{1}^{0.5}X_{2}^{0.5}$ 的间接效用函数为 $V=\dfrac{I}{2\sqrt{P_{1}P_{2}}}$。用罗伊恒等式求 $X_{1}$ 的马歇尔需求，并代入 $P_{1}=10,\ P_{2}=1,\ I=100$ 验证。`,
      a: R`$$-\frac{\partial V/\partial P_{1}}{\partial V/\partial I}=-\frac{-I/\left(4\sqrt{P_{1}^{3}P_{2}}\right)}{1/\left(2\sqrt{P_{1}P_{2}}\right)}=\frac{I}{2P_{1}}=X_{1}$$ 代入得 $X_{1}=\dfrac{100}{2\times10}=5$，与效用最大化直接求解一致——罗伊恒等式由间接效用反推马歇尔需求。`,
      src: '2016 北大光华 431 真题' } ],
    cu38: { q: R`谢泼德引理`,
      a: R`$$h_{i}=\frac{\partial E}{\partial p_{i}}$$` },
    mk01: { q: R`完全竞争市场的特征`,
      a: R`大量买卖者、产品同质、信息完全、进出自由（价格接受者）。` },
    mk02: { q: R`完全竞争厂商面临的需求曲线`,
      a: R`一条水平线 $P=P_{0}$（$P=AR=MR$）。` },
    rv12: { q: R`完全竞争厂商的短期供给曲线`,
      a: R`边际成本曲线在 $AVC_{\min}$ 以上的部分。` },
    mk05: { q: R`垄断市场的特征`,
      a: R`单一卖者、无相近替代品、进入壁垒高（价格制定者）。` },
    mk11: [{ q: R`某卫星电视公司在两地出售产品：北京需求 $Q_{B}=60-0.25P_{B}$，天津需求 $Q_{T}=100-0.5P_{T}$，总成本 $C(Q)=1000+40Q$，$Q=Q_{B}+Q_{T}$。(1) 求两地分别定价时的最优价格、销量及利润；(2) 求两地统一定价时的价格、销量及利润；(3) 哪种定价厂商利润更大？用消费者剩余判断消费者偏好哪种。`,
      a: R`(1) 反需求 $P_{B}=240-4Q_{B},\ P_{T}=200-2Q_{T}$。由 $MR=MC$：$MR_{B}=240-8Q_{B}=40\Rightarrow Q_{B}=25,\ P_{B}=140$；$MR_{T}=200-4Q_{T}=40\Rightarrow Q_{T}=40,\ P_{T}=120$。利润 $=140\times25+120\times40-(1000+40\times65)=4700$。(2) 统一定价 $P$：$Q=60-0.25P+100-0.5P=160-0.75P$，即 $P=\dfrac{640}{3}-\dfrac{4}{3}Q$，$MR=\dfrac{640}{3}-\dfrac{8}{3}Q=40\Rightarrow Q=65,\ P=\dfrac{380}{3}\approx126.67$，利润 $=\dfrac{380}{3}\times65-3600=\dfrac{13900}{3}\approx4633.33$。(3) 厂商偏好价格歧视（$4700>4633.33$）。消费者剩余：价格歧视下 $CS=\dfrac{1}{2}(240-140)\times25+\dfrac{1}{2}(200-120)\times40=2850$；统一定价下 $CS=\dfrac{14450}{9}+\dfrac{12100}{9}=2950$。故消费者偏好统一定价（$2950>2850$）。`,
      src: '2015 北大光华 431 真题' },
    { q: R`企业边际成本 $MC=10$。国内市场消费者购买 $x$ 单位效用 $26x-2x^2$，国外市场消费者购买 $x$ 单位效用 $14x-x^2$。(1) 企业能区分国内外消费者时求总销量；(2) 无法区分时求总销量。`,
      a: R`逆需求：国内 $P_d=26-4x_d$，国外 $P_f=14-2x_f$。(1) 三级价格歧视，$MR_d=MR_f=MC$：$$26-8x_d=10\Rightarrow x_d=2,\ P_d=18;\qquad 14-4x_f=10\Rightarrow x_f=1,\ P_f=12$$ 总销量 $=2+1=3$。(2) 统一定价 $P$：$x_d=\frac{26-P}{4}$（$P\le26$）、$x_f=\frac{14-P}{2}$（$P\le14$）。若只服务国内（$P>14$）：$\pi=(P-10)\frac{26-P}{4}$，一阶条件 $36-2P=0\Rightarrow P=18,\ Q=2,\ \pi=16$；若两市场都服务（$P\le14$）：$\pi=(P-10)\frac{54-3P}{4}$，最优 $P=14$（此时 $x_f=0$），$\pi=12$。故统一价 $P=18$、只服务国内，总销量 $=2$——价格歧视使厂商也服务了国外市场、总产量更大。`,
      src: '2026 北大光华 431 真题' } ],
    mk12: [{ q: R`三级价格歧视中，弹性较小的市场定价如何？`,
      a: R`定价更高。` },
    { q: R`（2015 真题）卫星电视公司在两地销售：北京需求 $Q_{B}=60-0.25P_{B}$、天津需求 $Q_{T}=100-0.5P_{T}$，总成本 $C(Q)=1000+40Q$。求两地分别定价的最优价格，并说明弹性与定价的关系。`,
      a: R`反需求 $P_{B}=240-4Q_{B},\ P_{T}=200-2Q_{T}$，由 $MR=MC=40$：$$MR_{B}=240-8Q_{B}=40\Rightarrow Q_{B}=25,\ P_{B}=140$$ $$MR_{T}=200-4Q_{T}=40\Rightarrow Q_{T}=40,\ P_{T}=120$$ 由勒纳指数 $|ε|=\frac{P}{P-MC}$：$|ε_{B}|=\frac{140}{100}=1.4<|ε_{T}|=\frac{120}{80}=1.5$。北京需求弹性较小、定价 $140>120$ 更高——弹性越小、加价能力越强。`,
      src: '2015 北大光华 431 真题' } ],
    mk13: { q: R`自然垄断的特征`,
      a: R`规模经济极强，$AC$ 持续下降，单一厂商供给成本最低。` },
    mk26: { q: R`两部收费的定价形式`,
      a: R`$$T=F+p\cdot q$$（固定费抽取消费者剩余，使用费接近边际成本）` },
    mk27: { q: R`捆绑销售的目的`,
      a: R`价格歧视或利用需求相关性。` },
    mk30: { q: R`某商品有 200 名高收入消费者（愿花 20 元购买）、300 名低收入消费者（愿花 10 元购买），厂商成本为每件 5 元。(1) 若厂商不能区分两类消费者，应如何定价使利润最大？(2) 现可购买大数据技术区分两类消费者，厂商最多愿花多少钱购买该技术？`,
      a: R`(1) 单一定价：定价 20 元时只有高收入者购买，利润 $200\times(20-5)=3000$；定价 10 元时两类都购买，利润 $500\times(10-5)=2500$。故定价 20 元、利润 3000 元（放弃低收入市场）。(2) 能区分即一级价格歧视：对高收入收 20、低收入收 10，利润 $=200\times15+300\times5=4500$。比 (1) 多赚 $1500$ 元，故最多愿为大数据技术支付 $1500$ 元（即打开低收入市场的新增利润，消费者剩余被完全榨取）。`,
      src: '2021 北大光华 431 真题' },
    wf03: { q: R`帕累托改进的含义`,
      a: R`至少使一人变好且无人变坏的调整。` },
    wf04: { q: R`交换的帕累托最优条件`,
      a: R`$$MRS^{A}_{XY}=MRS^{B}_{XY}$$` },
    wf05: { q: R`生产的帕累托最优条件`,
      a: R`$$MRTS^{X}_{LK}=MRTS^{Y}_{LK}$$` },
    wf06: { q: R`交换与生产同时最优的条件`,
      a: R`$$MRS_{XY}=MRT_{XY}$$` },
    wf09: { q: R`福利经济学第一定理`,
      a: R`完全竞争的一般均衡是帕累托最优的。` },
    wf10: { q: R`福利经济学第二定理`,
      a: R`在凸性条件下，任一帕累托最优都可经初始禀赋再分配由竞争均衡实现。` },
    wf12: [{ q: R`无谓损失的含义`,
      a: R`因偏离竞争均衡（征税、垄断、价格管制）造成的总剩余损失。` },
    { q: R`（2016 真题）完全竞争钢铁市场：私人均衡 $Q=9,\ P=11$；社会最优 $Q^{*}=7.2$；污染边际损耗 $MD=0.5Q$。求负外部性造成的无谓损失。`,
      a: R`$$DWL=\frac12\times MD(Q)\times(Q-Q^{*})=\frac12\times(0.5\times9)\times(9-7.2)=\frac12\times4.5\times1.8=4.05$$ 负外部性使私人产量 $9$ 超过社会最优 $7.2$，$[7.2,9]$ 区间的过度生产带来净社会损失——偏离最优水平造成的总剩余损失即无谓损失。`,
      src: '2016 北大光华 431 真题' } ],
    wf14: { q: R`功利主义社会福利函数`,
      a: R`$$W=U_{1}+U_{2}$$` },
    wf23: { q: R`社会无差异曲线的含义`,
      a: R`给定社会总福利水平的两产品组合轨迹。` },
    wf24: { q: R`卡尔多-希克斯补偿原则`,
      a: R`若受益者所得足以补偿受损者（潜在帕累托改进），即为有效率。` },
    gm01: [{ q: R`博弈的三个基本要素`,
      a: R`参与人、策略、支付。` },
    { q: R`（2013 真题）王刚与李红组成小组完成作业：通过则每人效用 3、不通过为 0；二人各选不努力 $N$（成本 0）、低努力 $l$（王刚成本 2、李红 1）或高努力 $h$（王刚 4、李红 3）。指出该博弈的三个基本要素。`,
      a: R`(1) 参与人：王刚、李红；(2) 策略：每人策略集 $\{N,l,h\}$；(3) 支付：通过得效用 $3$ 再减去各自努力成本（如 $(l,l)$ 时王刚 $3-2=1$、李红 $3-1=2$）。由三要素即可构造支付矩阵并求解纳什均衡。`,
      src: '2013 北大光华 431 真题' } ],
    gm02: { q: R`占优策略的含义`,
      a: R`无论对手选择什么，都是自己最优选择的策略。` },
    gm03: { q: R`占优策略均衡`,
      a: R`每个参与人都选择占优策略所构成的均衡。` },
    gm06: { q: R`占优策略均衡与纳什均衡的关系`,
      a: R`占优策略均衡一定是纳什均衡，反之不一定。` },
    gm07: { q: R`混合策略的含义`,
      a: R`参与人以一定概率在纯策略之间随机选择。` },
    gm08: [{ q: R`两个投机者同时决定是否卖空某股票。卖空者支付成本 $c=2$，收益 $v=1.5N$（$N$ 为卖空人数）；不卖空者成本与收益均为 0。(1) 求全部纯策略纳什均衡；(2) 求混合策略纳什均衡。`,
      a: R`(1) 支付矩阵（行/列）：都卖空 $(1,1)$；仅一方卖空时，卖空者 $-0.5$、对方 $0$；都不卖空 $(0,0)$。纯策略纳什均衡：都卖空（偏离得 $0<1$）与都不卖空（偏离得 $-0.5<0$）。(2) 设对手以概率 $q$ 卖空，则我卖空的期望支付 $=q\times1+(1-q)\times(-0.5)=1.5q-0.5$，不卖空为 $0$。令 $1.5q-0.5=0\Rightarrow q=\dfrac{1}{3}$。故混合策略纳什均衡为：双方各以 $\dfrac{1}{3}$ 概率卖空、$\dfrac{2}{3}$ 概率不卖空。`,
      a2: R`💡 巧解（对称无差异）：博弈对两投机者完全对称，混合均衡必为双方同概率 $q$。直接令一方在「卖空」与「不卖空」间无差异：$q\cdot1+(1-q)\cdot(-0.5)=0\Rightarrow q=\dfrac13$，一步得解，无需列出完整矩阵再逐格检验。`,
      src: '2025 北大光华 431 真题' },
    { q: R`三个厂商各自决定是否进入市场，进入后收入为 $150/n$（$n$ 为进入者数），生产成本 $c\in(50,75)$。(1) 求全部纯策略纳什均衡；(2) 求唯一的对称混合纳什均衡。`,
      a: R`(1) 进入 $n$ 家的利润 $=\frac{150}{n}-c$。$n=1$：$150-c\in(75,100)>0$；$n=2$：$75-c\in(0,25)>0$；$n=3$：$50-c<0$。故均衡为**恰好两家进入**（任取 3 家中的 2 家，共 3 个纯策略纳什均衡）。(2) 设每家以概率 $p$ 进入，无差异条件：进入的期望支付 $=(1-p)^2(150-c)+2p(1-p)(75-c)+p^2(50-c)$ 等于不进入的 0，展开得 $50p^2-150p+(150-c)=0$，取 $p\in(0,1)$ 的根：$$p=\frac{3-\sqrt{2c/25-3}}{2}$$ 即唯一的对称混合纳什均衡。`,
      src: '2021 北大光华 431 真题' },
    { q: R`两个股票投资者同时选择卖空或放弃。卖空成本 $100$，放弃成本 $0$；若两人都卖空则各获利 $200$；若只有一人卖空或无人卖空，则二人收益均为 $0$。(1) 同时决策时求纳什均衡；(2) 先后决策且后手能观察先手，求子博弈精炼均衡。`,
      a: R`(1) 支付矩阵（行/列）：都卖空 $(200-100,200-100)=(100,100)$；仅一人卖空时卖空者 $0-100=-100$、对方 $0$；都不卖空 $(0,0)$。最优反应：对手卖空则我卖空（$100>0$），对手放弃则我放弃（$0>-100$），故纯策略纳什均衡为 $(卖空,卖空)$ 与 $(放弃,放弃)$。(2) 序贯下逆向归纳：先手卖空 $\Rightarrow$ 后手卖空（$100>0$）；先手放弃 $\Rightarrow$ 后手放弃（$0>-100$）。先手比较卖空得 $100$、放弃得 $0$，故选卖空。子博弈精炼均衡：双方都卖空，收益 $(100,100)$（$(放弃,放弃)$ 不是精炼均衡，因在"先手已卖空"的子博弈上后手选放弃非最优）。`,
      src: '2024 北大光华 431 真题' } ],
    gm09: [{ q: R`（接王刚-李红作业博弈）若李红先选择努力水平、王刚观察到后再选择，用逆向归纳法求子博弈精炼纳什均衡。`,
      a: R`王刚（后手）对李红各行动的最优反应：李红选 $N$ 时王刚选 $N$（得 0）；李红选 $l$ 时王刚选 $l$（得 1）；李红选 $h$ 时王刚选 $N$（得 3）。故李红比较：选 $N$ 得 $0$、选 $l$ 得 $2$、选 $h$ 得 $0$，最优选 $l$。子博弈精炼纳什均衡为：李红选 $l$，王刚按「$N\to N,\ l\to l,\ h\to N$」反应，均衡支付为（王刚 1，李红 2）。`,
      src: '2013 年北大光华 431 真题' },
    { q: R`公司 1、2 生产同质产品、成本为 0，同时定产，需求 $P=12-q$（$q=q_1+q_2$）。(1) 求古诺纳什均衡与利润；(2) 公司 2 被强制 $q_2=0$ 时公司 1 的垄断利润；(3) 公司 1 可先贿赂公司 2 使其退出，公司 2 决定是否接受（接受则公司 1 垄断、公司 2 得贿赂；拒绝则回到 (1) 的博弈），求子博弈精炼均衡与利润；(4) 公司 3 加入（$q_3\ge0$，单位成本 2），求三厂商古诺纳什均衡与利润；(5) 公司 1 可否贿赂公司 3 退出？求子博弈精炼均衡。`,
      a: R`(1) 古诺 $q_1=q_2=\frac{12-0}{3}=4$，$P=4$，$\pi_1=\pi_2=16$。(2) 垄断 $MR=12-2q=0\Rightarrow q=6,\ P=6,\ \pi=36$。(3) 公司 2 退出可得贿赂，其保留效用为古诺利润 16；公司 1 垄断利润 36。贿赂额 $B$ 满足 $16\le B\le20$（公司 2 接受、公司 1 仍优于古诺），SPE：公司 1 出价 $B\in[16,20]$、公司 2 接受，$\pi_1=36-B,\ \pi_2=B$（如 $B=16$ 时 $\pi_1=20,\pi_2=16$）。(4) 三厂商（$c_1=c_2=0,\ c_3=2$）：$$q_i=\frac{a-(n+1)c_i+\sum c_j}{(n+1)b}\Rightarrow q_1=q_2=3.5,\ q_3=1.5,\ P=3.5$$ $$\pi_1=\pi_2=12.25,\quad \pi_3=(3.5-2)\times1.5=2.25$$ (5) 公司 3 退出后公司 1、2 回到双寡头古诺（各得 16），公司 3 保留效用 2.25。公司 1 因 3 退出多得 $16-12.25=3.75$，故贿赂 $B\in[2.25,3.75]$，公司 3 接受；SPE：公司 1 出价 $B=2.25$、公司 3 接受，$\pi_1=13.75,\ \pi_2=16$（公司 2 搭便车）、$\pi_3=2.25$。`,
      src: '2017 北大光华 431 真题' } ],
    gm12: { q: R`张三、李四序贯博弈：行动集 $\{L,R\}$。张三先选 $A$，李四观察到后选 $B$。若 $A=B=L$ 则收益 $(3,1)$；若 $A=B=R$ 则 $(1,3)$；若 $A\neq B$ 则 $(0,0)$。(1) 求子博弈精炼纳什均衡；(2) 求一个不同于 (1) 的纯策略纳什均衡，并说明它为何不是子博弈精炼均衡。`,
      a: R`(1) 逆向归纳：李四的最优反应为"观察到 $L$ 选 $L$（得 1）、观察到 $R$ 选 $R$（得 3）"。张三比较：选 $L$ 得 3、选 $R$ 得 1，故选 $L$。子博弈精炼均衡：张三选 $L$，李四按 $(L,L)$ 反应，均衡支付 $(3,1)$。(2) 纯策略纳什均衡还有"张三选 $R$、李四恒选 $R$"，支付 $(1,3)$（张三偏离到 $L$ 会因李四仍选 $R$ 得 0，故不偏离）。但它不是子博弈精炼均衡：在"张三选 $L$"这一未到达的子博弈上，李四选 $R$（得 0）并非最优（应选 $L$ 得 1）。即"你选 L 我也选 R"是不可置信威胁，被逆向归纳剔除。`,
      src: '2021 北大光华 431 真题' },
    gm13: [{ q: R`贝叶斯博弈`,
      a: R`类型为私人信息，用信念与期望支付求贝叶斯纳什均衡。` },
    { q: R`（2015 真题）小李先行动选 $H$ 或 $L$，小王看不到小李的行动，只能收到信号 $h$ 或 $l$，且 $\Pr(h|H)=p,\ \Pr(l|H)=1-p,\ \Pr(h|L)=q,\ \Pr(l|L)=1-q$（$p>0.5>q$），小王观测信号后选 $A$ 或 $B$。这是典型的贝叶斯博弈——指出类型、信号与信念，并求 $p=1,q=0$ 时的纯策略纳什均衡。`,
      a: R`小李的类型（$H/L$）为私人信息，小王依据信号更新信念（如 $\Pr(H|h)$）并按期望支付行动。$p=1,q=0$ 时信号完全揭示类型（$h\Rightarrow H,\ l\Rightarrow L$）：小李选 $H$ 时小王最优反应 $A$（得 $2>1$）、选 $L$ 时最优反应 $B$；小李比较 $(H,A)$ 得 $5$ 与 $(L,B)$ 得 $4$，选 $H$。均衡：小李选 $H$，小王策略 $h\to A,\ l\to B$，支付 $(5,2)$。`,
      src: '2015 北大光华 431 真题' } ],
    gm20: [{ q: R`逆向归纳法`,
      a: R`从博弈最后阶段向前求解子博弈精炼纳什均衡。` },
    { q: R`（2024 真题）两个股票投资者先后决策（后决策者能观察先者）：卖空成本 100、放弃成本 0；若两人都卖空则各获利 200，若只有一人卖空或无人卖空则收益均为 0。用逆向归纳求子博弈精炼均衡。`,
      a: R`逆向归纳：若先手卖空，后手最优卖空（$200-100=100>0$）；若先手放弃，后手最优放弃（$0>-100$）。先手比较：卖空得 $100$、放弃得 $0$，故选卖空。子博弈精炼均衡：双方都卖空，收益 $(100,100)$——从最后阶段向前倒推，剔除不可置信威胁。`,
      src: '2024 北大光华 431 真题' } ],
    pd13: { q: R`既定成本下产量最大化的条件`,
      a: R`$$\frac{MP_{L}}{w}=\frac{MP_{K}}{r}$$` },
    cu03: { q: R`边际效用递减规律`,
      a: R`其他商品消费量不变时，随某商品消费增加，其边际效用递减。` },
    cu06: [{ q: R`预算线 $P_{1}X_{1}+P_{2}X_{2}=I$ 的斜率`,
      a: R`$$-\frac{P_{1}}{P_{2}}$$` },
    { q: R`（2013 真题）一单位大米需 2 元货币+1 元粮票，一单位油需 1 元货币+1 元粮票；该人持有货币 60 元、粮票 30 元。写出货币与粮票两个预算约束，并求其斜率。`,
      a: R`货币约束 $$2x_{1}+x_{2}\le60$$ 斜率 $-\dfrac{2}{1}=-2$；粮票约束 $$x_{1}+x_{2}\le30$$ 斜率 $-1$。预算线斜率即两种商品（有效）价格比之负；货币与粮票不可互换时，可行消费集取两约束的交集。`,
      src: '2013 北大光华 431 真题' } ],
    cu07: [{ q: R`无差异曲线的特征`,
      a: R`向右下倾斜、凸向原点、互不相交、离原点越远效用越高。` },
    { q: R`（2018 真题）小丽效用 $u=x+y$，小贾效用 $u=\max\{x,y\}$。分别画出两人的无差异曲线，并说明其形状。`,
      a: R`小丽 $u=x+y$：无差异曲线为斜率 $-1$ 的直线（完全替代，向右下倾斜、弱凸）；小贾 $u=\max\{x,y\}$：无差异曲线为沿两轴的直角折线（折角在 $x=y$ 处），偏好集非凸。完全替代与 $\max$ 型是凸偏好与"光滑凸向原点"无差异曲线的两个典型例外。`,
      src: '2018 北大光华 431 真题' } ],
    cu09: { q: R`边际替代率递减规律`,
      a: R`沿无差异曲线，随 $X_{1}$ 增加，$MRS$ 递减。` },
    cu13: { q: R`股票市场中常见"追涨杀跌"（价格上涨时买入量增加）。请判断股票是否属于吉芬商品，并解释"追涨"现象的成因。`,
      a: R`股票不是吉芬商品。吉芬商品须是低档品，且价格上升引起需求量上升的机制是**负的收入效应超过替代效应**（价格↑→实际收入↓→因是低档品反而多买）。而"追涨"机制完全不同：股票是资产而非当期消费品，其价格上涨不通过实际收入效应作用于当期需求，而是投资者预期价格继续上涨（正反馈/动量交易、信息信号）而买入。二者成因与机制均不同，故"追涨"不能证明股票是吉芬商品。`,
      src: '2026 北大光华 431 真题' },
    cu15: { q: R`奶茶店做奶茶要加椰果（$X_1$）与珍珠（$X_2$）两种配料，消费者对一杯奶茶有完全替代效用 $U=2X_1+3X_2$，两种配料对奶茶店的单位成本相同。奶茶店应如何分配椰果与珍珠的比例？`,
      a: R`两种配料单位成本相同，比较边际效用：$$MU_1=2<MU_2=3$$ 即每单位成本下珍珠带来的效用更高。完全替代品在预算线上比较单位成本的边际效用，故最优为**角点解**——全部使用珍珠（$X_1=0$，$X_2$ 用尽预算），椰果与珍珠比例为 $0:1$。`,
      src: '2021 北大光华 431 真题' },
    cu17: { q: R`CES 效用函数的形式`,
      a: R`$$U=(X^{\rho}+Y^{\rho})^{1/\rho}$$` },
    cu18: [{ q: R`马歇尔需求函数`,
      a: R`效用最大化得到的 $X=X(P_{X},P_{Y},I)$。` },
    { q: R`（2016 真题）甲、乙效用均为 $U(X_{1},X_{2})=X_{1}^{0.5}X_{2}^{0.5}$，价格 $P_{1}=10,\ P_{2}=1$，收入 $I=100$。求两人的马歇尔需求函数及最优消费量（乙有馅饼折扣券，可用半价购买任意数量馅饼）。`,
      a: R`柯布-道格拉斯马歇尔需求 $$X_{1}=\frac{a}{a+b}\cdot\frac{I}{P_{1}}=\frac{I}{2P_{1}},\qquad X_{2}=\frac{I}{2P_{2}}$$ 甲（$P_{1}=10$）：$X_{1}=5,\ X_{2}=50$；乙（券后 $P_{1}=5$）：$X_{1}=10,\ X_{2}=50$。马歇尔需求由效用最大化直接解得，是价格与收入的函数。`,
      src: '2016 北大光华 431 真题' } ],
    cu19: { q: R`恩格尔曲线`,
      a: R`收入与需求量关系：正常品正斜率、低档品负斜率。` },
    cu21: [{ q: R`间接效用函数`,
      a: R`最大效用作为价格与收入的函数 $V(P_{X},P_{Y},I)$。` },
    { q: R`（2016 真题）消费者效用 $U=X_{1}^{0.5}X_{2}^{0.5}$，价格 $P_{1}=10,\ P_{2}=1$，收入 $I=100$。求其间接效用函数及均衡效用。`,
      a: R`把马歇尔需求代入效用函数：$$V(P_{1},P_{2},I)=\left(\frac{I}{2P_{1}}\right)^{0.5}\left(\frac{I}{2P_{2}}\right)^{0.5}=\frac{I}{2\sqrt{P_{1}P_{2}}}$$ 甲：$$V(10,1,100)=\frac{100}{2\sqrt{10}}=5\sqrt{10}\approx15.81$$ 间接效用只取决于价格与收入，是价格变动的福利度量基础。`,
      src: '2016 北大光华 431 真题' } ],
    cu22: { q: R`支出函数`,
      a: R`达到某效用水平的最小支出 $E(P_{X},P_{Y},U)$。` },
    cu23: { q: R`希克斯（补偿）需求`,
      a: R`既定效用下支出最小化的需求，只反映替代效应。` },
    cu25: [{ q: R`消费者均衡何时出现角点解？`,
      a: R`$MRS$ 与价格比在端点处仍不相等（如完全替代品）。` },
    { q: R`（2021 真题）奶茶店做奶茶加椰果（$X_{1}$）与珍珠（$X_{2}$）两种配料，消费者对一杯奶茶有完全替代效用 $U=2X_{1}+3X_{2}$，两种配料对奶茶店的单位成本相同。奶茶店应如何分配椰果与珍珠的比例？`,
      a: R`完全替代偏好无内点解：比较单位成本的边际效用，$$MU_{1}=2<MU_{2}=3$$ 珍珠的单位成本效用更高，故最优为角点解——全部使用珍珠（$X_{1}=0$），比例为 $0:1$。当 $MRS$ 与价格比在端点处仍不相等时，均衡取角点。`,
      src: '2021 北大光华 431 真题' } ],
    cu26: { q: R`基数效用论中需求曲线的推导依据`,
      a: R`$\dfrac{MU}{P}=\lambda$ 且 $MU$ 递减。` },
    cu27: { q: R`价格消费曲线的含义`,
      a: R`一种商品价格变动时均衡点的轨迹，可导出需求曲线。` },
    cu28: { q: R`正常品与低档品收入效应的符号`,
      a: R`正常品收入效应为正，低档品为负。` },
    cu40: { q: R`拟线性效用函数的特征`,
      a: R`$$U=x+v(y)$$ 收入效应为零。` },
    it01: [{ q: R`两期预算约束（现值形式）`,
      a: R`$$C_{1}+\frac{C_{2}}{1+r}=Y_{1}+\frac{Y_{2}}{1+r}$$` },
    { q: R`（2024 真题）消费者第一期收入 $y_{1}=2$、第二期收入 $y_{2}=1$，可购买利率 $10\%$ 的无风险国债，效用 $u=\ln c_{t}$（折现率 1）。(1) 写出两期预算约束（现值形式）；(2) 求最优国债购买量。`,
      a: R`(1) 现值形式预算约束 $$c_{1}+\frac{c_{2}}{1.1}=2+\frac{1}{1.1}$$ (2) 设买国债 $b$：$c_{1}=2-b$、$c_{2}=1+1.1b$，最大化 $\ln(2-b)+\ln(1+1.1b)$，一阶条件 $$-\frac{1}{2-b}+\frac{1.1}{1+1.1b}=0\Rightarrow b=\frac{6}{11}\approx0.545$$ 即买约 $0.545$ 单位国债（第一期储蓄）。`,
      src: '2024 北大光华 431 真题' } ],
    it02: [{ q: R`消费者两期消费 $c_{0},c_{1}$，两期价格均为 1，今天收入 $I_{0}=100$、明天收入 $I_{1}=34$，效用 $U=\ln c_{0}+\ln c_{1}$，利率 $r=0$，只能储蓄、不能借款。(1) 求其消费决策；(2) 若明天收入以各 50% 概率为 $100$ 或 $0$，求其消费决策。`,
      a: R`(1) 跨期最优 $MRS=\dfrac{MU_{0}}{MU_{1}}=\dfrac{c_{1}}{c_{0}}=1+r=1\Rightarrow c_{1}=c_{0}$。预算（现值）$c_{0}+c_{1}=100+34=134$，故 $c_{0}=c_{1}=67$（$c_{0}=67\le100$ 不需借款，储蓄 33）。(2) 令储蓄 $s=100-c_{0}$，$c_{1}=s+I_{1}$。期望效用 $U=\ln c_{0}+\dfrac{1}{2}\ln(200-c_{0})+\dfrac{1}{2}\ln(100-c_{0})$，一阶条件 $\dfrac{1}{c_{0}}=\dfrac{1}{2}\left(\dfrac{1}{200-c_{0}}+\dfrac{1}{100-c_{0}}\right)$，整理得 $c_{0}^{2}-225c_{0}+10000=0$，取可行解 $c_{0}=\dfrac{225-25\sqrt{17}}{2}\approx60.96$，储蓄 $s\approx39.04$。`,
      src: '2016 北大光华 431 真题' },
    { q: R`两期决策：初始财富 $W$，第一期消费 $C_1$ 与储蓄 $S$（$C_1+S=W$），第二期消费 $C_2=RS$（$R$ 为储蓄收益率）。效用 $U=-\frac{1}{C_1}-\frac{\beta}{C_2}$（$0<\beta<1$）。(1) $R=\mu$ 为确定常数时求 $C_1,S$，并说明 $\mu$ 上升时储蓄如何变化；(2) $R\sim U[\mu-\epsilon,\mu+\epsilon]$（$0<\epsilon<\mu$）时，决策者最大化 $-\frac1{C_1}-\beta\,E[\frac1{C_2}]$，求 $C_1,S$；(3) 比较 (1)(2) 的储蓄，$\epsilon$ 上升时储蓄如何变化？`,
      a: R`(1) 最大化 $-\frac{1}{W-S}-\frac{\beta}{\mu S}$，一阶条件 $-\frac{1}{(W-S)^2}+\frac{\beta}{\mu S^2}=0$：$$\frac{S}{W-S}=\sqrt{\frac{\beta}{\mu}}\ \Rightarrow\ S=\frac{W\sqrt{\beta/\mu}}{1+\sqrt{\beta/\mu}},\quad C_1=W-S$$ $\mu$ 上升使 $S$ **下降**（$u=-1/C$ 下收入效应占优）。(2) 记 $A=E[\frac1R]=\frac{1}{2\epsilon}\ln\frac{\mu+\epsilon}{\mu-\epsilon}$，最大化 $-\frac{1}{W-S}-\frac{\beta A}{S}$，一阶条件 $\frac{S}{W-S}=\sqrt{\beta A}$，得 $$S=\frac{W\sqrt{\beta A}}{1+\sqrt{\beta A}}$$ (3) 由 $1/R$ 的凸性，$A=E[1/R]>\frac{1}{E[R]}=\frac1\mu$，故 (2) 的储蓄**高于** (1)——风险收益率引发预防性储蓄；$\epsilon$ 上升使 $A$ 增大，储蓄进一步上升。`,
      src: '2023 北大光华 431 真题' } ],
    it03: [{ q: R`现值公式`,
      a: R`$$PV=\frac{FV}{(1+r)^{t}}$$` },
    { q: R`（2019 真题）某人在当期持现金 $x_{0}$，投资项目以概率 $P$ 在下一期带来 $x_{1}$、以 $1-P$ 在再下一期带来 $x_{2}$，市场无风险利率为 $r$。用现值公式写出投资的期望现值，并求风险中性者投资与不投资无差异时的 $P$。`,
      a: R`期望现值（按现值公式 $PV=FV/(1+r)^{t}$ 折现）：$$PV=P\cdot\frac{x_{1}}{1+r}+(1-P)\cdot\frac{x_{2}}{(1+r)^{2}}$$ 风险中性者无差异即期望现值等于不投资的 $x_{0}$：$$x_{0}=P\frac{x_{1}}{1+r}+(1-P)\frac{x_{2}}{(1+r)^{2}}\Rightarrow P=\frac{x_{0}-\frac{x_{2}}{(1+r)^{2}}}{\frac{x_{1}}{1+r}-\frac{x_{2}}{(1+r)^{2}}}$$`,
      src: '2019 北大光华 431 真题' } ],
    it04: { q: R`终值公式`,
      a: R`$$FV=PV(1+r)^{t}$$` },
    it05: [{ q: R`储蓄者与借贷者的识别`,
      a: R`当前消费小于收入者为储蓄者，大于收入者为借贷者。` },
    { q: R`（2016 真题）消费者今天收入 $I_{0}=100$、明天收入 $I_{1}=34$，效用 $U=\ln c_{0}+\ln c_{1}$，利率 $r=0$，只能储蓄不能借款。求最优消费决策，并判断该消费者是储蓄者还是借贷者。`,
      a: R`跨期最优 $MRS=\dfrac{c_{1}}{c_{0}}=1+r=1\Rightarrow c_{1}=c_{0}$；预算 $c_{0}+c_{1}=134$，故 $c_{0}=c_{1}=67$。当前消费 $c_{0}=67<100=I_{0}$，储蓄 $33$——当前消费小于收入，是**储蓄者**（约束"只能储蓄"自动满足）。`,
      src: '2016 北大光华 431 真题' } ],
    it06: [{ q: R`利率上升对储蓄的影响`,
      a: R`替代效应（多储蓄）与收入效应（少储蓄）方向相反，净效应不确定。` },
    { q: R`（2023 真题）两期决策：初始财富 $W$，第一期消费 $C_{1}$ 与储蓄 $S$，第二期消费 $C_{2}=\mu S$（$\mu>1$ 为确定储蓄收益率），效用 $U=-\frac{1}{C_{1}}-\frac{\beta}{C_{2}}$（$0<\beta<1$）。求最优储蓄 $S$，并说明 $\mu$ 上升时储蓄如何变化。`,
      a: R`最大化 $-\frac{1}{W-S}-\frac{\beta}{\mu S}$，一阶条件 $\frac{S}{W-S}=\sqrt{\frac{\beta}{\mu}}$，得 $$S=\frac{W\sqrt{\beta/\mu}}{1+\sqrt{\beta/\mu}}$$ $\mu$ 上升使 $S$ **减少**——对 $u=-1/C$，利率上升的收入效应（提高未来财富、减少储蓄）超过替代效应（多储蓄）。说明利率对储蓄的影响方向取决于效用函数，净效应不确定。`,
      src: '2023 北大光华 431 真题' } ],
    it07: { q: R`永续年金现值`,
      a: R`$$PV=\frac{C}{r}$$` },
    it08: { q: R`名义利率与实际利率（费雪方程）`,
      a: R`$$1+r=\frac{1+i}{1+\pi}\approx i-\pi$$` },
    cu12: { q: R`价格变动的总效应如何分解？`,
      a: R`总效应 = 替代效应 + 收入效应。` },
    cu20: { q: R`显示偏好弱公理 WARP`,
      a: R`若 $A$ 直接显示偏好于 $B$，则在 $B$ 可负担时不能选择 $B$ 显示偏好于 $A$。` },
    cu31: [{ q: R`甲、乙二人效用函数均为 $U=X_{1}^{1/2}X_{2}^{1/2}$，价格 $P_{1}=10,\ P_{2}=1$，收入均为 $I=100$。乙有一张馅饼折扣券，能以半价（$P_{1}=5$）购买馅饼 $X_{1}$（只用一次），甲没有。(1) 求二人各自最优消费量；(2) 甲为得到该券最高愿付多少钱？(3) 乙出让该券至少应得多少钱？(4) 二人能否达成转让协议？`,
      a: R`(1) 甲（无券）：$X_{1}=\dfrac{I}{2P_{1}}=\dfrac{100}{20}=5$，$X_{2}=\dfrac{100}{2}=50$，$U_{\text{甲}}=\sqrt{5\times50}=5\sqrt{10}$；乙（有券）：$X_{1}=\dfrac{100}{2\times5}=10$，$X_{2}=50$，$U_{\text{乙}}=\sqrt{10\times50}=10\sqrt{5}$。(2) 甲愿付（等价变化）：持券后收入 $m$ 时效用为 $\dfrac{m}{\sqrt{20}}$，令 $\dfrac{m}{\sqrt{20}}=5\sqrt{10}\Rightarrow m=\sqrt{20\times250}=50\sqrt{2}\approx70.71$，故最高愿付 $100-50\sqrt{2}\approx29.29$ 元。(3) 乙愿收（补偿变化）：无券下收入 $m'$ 时效用为 $\dfrac{m'}{\sqrt{40}}$，令 $\dfrac{m'}{\sqrt{40}}=10\sqrt{5}\Rightarrow m'=\sqrt{40\times500}=100\sqrt{2}\approx141.42$，故至少应得 $100\sqrt{2}-100\approx41.42$ 元。(4) 因甲愿付 $29.29$ 元 $<$ 乙愿收 $41.42$ 元，估价不相容，无法达成转让协议。`,
      src: '2016 北大光华 431 真题' },
    { q: R`市民两种出行方式：公共交通 $x_1$（原价 $p_1$ 元/公里，现补贴 50% 即 $0.5p_1$）与私家车 $x_2$（成本 $p_2$ 元/公里），效用 $u(x_1,x_2)=x_1^{0.2}x_2^{0.8}$，月收入 $M$。专家建议取消价格补贴、改发固定收入补贴 $s$ 元，使效用前后无差异。(1) 求最小的 $s$；(2) 改补贴后市民的 $x_1,x_2$；(3) 哪种补贴财政负担小、差多少？`,
      a: R`(1) 补贴时 $x_1=\frac{0.2M}{0.5p_1}=\frac{0.4M}{p_1},\ x_2=\frac{0.8M}{p_2}$，效用 $V_1=(0.4M/p_1)^{0.2}(0.8M/p_2)^{0.8}$。取消补贴后收入 $M+s$，$V_2=(0.2(M+s)/p_1)^{0.2}(0.8(M+s)/p_2)^{0.8}$。令 $V_1=V_2$：$$0.4^{0.2}M=0.2^{0.2}(M+s)\Rightarrow s=(2^{0.2}-1)M\approx0.149M$$ (2) $x_1=\frac{0.2(M+s)}{p_1},\quad x_2=\frac{0.8(M+s)}{p_2}$。(3) 价格补贴的财政成本 $=0.5p_1\cdot\frac{0.4M}{p_1}=0.2M$；固定补贴成本 $s\approx0.149M<0.2M$。故**固定收入补贴更省钱**，少花 $0.2M-0.149M\approx0.051M$——不扭曲相对价格的收入补贴能达到同样的效用。`,
      src: '2020 北大光华 431 真题' } ],
    cu32: { q: R`希克斯替代效应`,
      a: R`维持原效用水平下价格变动引起的需求变化。` },
    cu33: { q: R`斯勒茨基替代效应`,
      a: R`维持原购买力下价格变动引起的需求变化。` },
    cu39: { q: R`强显示偏好公理 SARP`,
      a: R`显示偏好关系不存在直接或间接的循环矛盾。` },
    un02: [{ q: R`期望值公式`,
      a: R`$$E(x)=\sum_{i}p_{i}x_{i}$$` },
    { q: R`（2013 真题）两居民房屋各值 $W$ 万元，每房失火概率 $P$、损失 $L$ 万元。(1) 不签风险共担协议时每人的房屋期望价值；(2) 签协议（一方失火获对方 $0.5L$ 补偿）时每人的期望价值。`,
      a: R`(1) 独立时 $$E=(1-P)W+P(W-L)=W-PL$$ (2) 共担时三状态加权：$$E=(1-P)^{2}W+2P(1-P)(W-0.5L)+P^{2}(W-L)=W-PL$$ 两方案期望价值相同（均值不变、方差变小）——期望值按状态概率加权求和。`,
      src: '2013 北大光华 431 真题' } ],
    un03: [{ q: R`风险厌恶者的效用函数特征`,
      a: R`$$u''(x)<0$$（凹函数）` },
    { q: R`（2026 真题）请给出风险规避的定义，并解释为什么通常假设大多数人是风险规避者。`,
      a: R`风险规避：决策者拒绝公平赌局（期望值等于现状的赌局），其效用函数为凹函数 $$u''(x)<0$$ 即边际效用递减。多数人风险规避的原因：财富的边际效用递减——同等金额的损失带来的效用减少大于等额收益带来的效用增加，故人们愿付保费消除风险（保险市场由此存在）。`,
      src: '2026 北大光华 431 真题' } ],
    un04: { q: R`某人在当期 $T_0$ 持现金 $x_0$，考虑投资。市场无风险利率为 $r$。一个项目以概率 $P$ 在下一期 $T_1$ 带来 $x_1$、以 $1-P$ 在再下一期 $T_2$ 带来 $x_2$（$x_1,x_2>x_0$）。此人为风险中性，且存在 $P$ 使投资与不投资无差异。(1) 求 $P$；(2) 第二个人每期效用为 $x^2$，面对同样的机会与利率，若 $P$ 取 (1) 的值，他会投资吗？`,
      a: R`(1) 风险中性者按现值比较：不投资效用 $x_0$；投资的期望现值 $=P\frac{x_1}{1+r}+(1-P)\frac{x_2}{(1+r)^2}$。无差异即 $$x_0=P\frac{x_1}{1+r}+(1-P)\frac{x_2}{(1+r)^2}\ \Rightarrow\ P=\frac{x_0-\frac{x_2}{(1+r)^2}}{\frac{x_1}{1+r}-\frac{x_2}{(1+r)^2}}$$ (2) $u=x^2$ 为凸函数（$u''=2>0$），风险偏好。该 $P$ 使项目的期望（折现）收益恰等于 $x_0$；凸效用下 $E[u]\ge u(E)$，故风险偏好者更愿意投资——风险中性者无差异的项目，风险爱好者会投资。`,
      src: '2019 北大光华 431 真题' },
    un07: [{ q: R`阿罗-普拉特绝对风险厌恶系数`,
      a: R`$$R_{A}=-\frac{u''(x)}{u'(x)}$$` },
    { q: R`（2015 真题）某人效用函数 $U(W)=W^{1/2}$。请判断其风险态度并求绝对风险厌恶系数。`,
      a: R`$$u'(W)=\frac{1}{2}W^{-1/2},\qquad u''(W)=-\frac14 W^{-3/2}<0$$ 效用凹，风险厌恶；$$R_{A}=-\frac{u''}{u'}=-\frac{-\frac14 W^{-3/2}}{\frac12 W^{-1/2}}=\frac{1}{2W}>0$$ $R_{A}>0$ 且随财富递减（财富越高越接近风险中性）。`,
      src: '2015 北大光华 431 真题' } ],
    un08: { q: R`相对风险厌恶系数`,
      a: R`$$R_{R}=-x\frac{u''(x)}{u'(x)}$$` },
    un09: [{ q: R`两居民房屋价值均为 $W$ 万元，独立时各自房屋失火概率为 $P$、损失 $L$ 万元。若二人签风险共担协议：一方失火后可获另一方 $0.5L$ 补偿。(1) 求两种情形下每人房屋的期望价值；(2) 风险中性者是否无差异？(3) 风险厌恶者偏好哪种安排？`,
      a: R`(1) 独立时每人期望价值 $$(1-P)W+P(W-L)=W-PL$$。共担时三种状态：都不失火（概率 $(1-P)^2$）值 $W$；仅一方失火（$2P(1-P)$）各值 $W-0.5L$；都失火（$P^2$）各值 $W-L$，期望 $$(1-P)^{2}W+2P(1-P)(W-0.5L)+P^{2}(W-L)=W-PL$$，与独立时相同。(2) 风险中性只关心期望值，两者期望相同，故无差异。(3) 共担把 $L$ 的损失摊成 $0.5L+0.5L$，是均值不变、方差变小的分布（如 $W=100,P=0.1,L=40$ 时方差由 $144$ 降至 $72$），风险厌恶者严格偏好风险共担。`,
      src: '2013 年北大光华 431 真题' },
    { q: R`两雇员工资均为 $M$，两商品价格 $P_1,P_2$。雇员 1 效用 $U_1=X_{11}^{1/2}+X_{12}^{1/2}$，雇员 2 效用 $U_2=X_{21}^{1/2}X_{22}^{1/2}$。企业将解雇一名雇员，二人被裁概率相同，被裁者收入为 $0$。(1) 若二人签契约：无论谁被裁都与对方平分收入（各得 $M/2$），二人都有动机签吗？(2) 若担心对方违约，请律师花 $x$ 元把契约写成可执行合同，由一方付补偿金 $T$ 保证收入相等，二人能接受的最大 $x$ 是多少？`,
      a: R`(1) 雇员 1 的效用关于 $(X_{11},X_{12})$ 齐次度为 $\tfrac12$，故间接效用 $V_1(M)\propto\sqrt{M}$（凹，风险厌恶）；雇员 2 的效用齐次度为 $1$，$V_2(M)\propto M$（线性，风险中性）。不签约期望效用 $\tfrac12 V_i(M)$，签约得 $V_i(M/2)$。雇员 1：$V_1(M/2)=V_1(M)/\sqrt2>\tfrac12 V_1(M)$，有动机；雇员 2：$V_2(M/2)=\tfrac12 V_2(M)$，无差异。故契约对 1 有利、对 2 中性（弱均可接受）。(2) 签约给雇员 1 的收益 $=(1/\sqrt2-\tfrac12)V_1(M)\approx0.207V_1(M)$；雇员 2 收益为 $0$。若律师费由二人分摊，雇员 2 愿付上限为 0，故二人**都能**接受的最大 $x=0$（只有风险厌恶的一方有投保动机）。`,
      src: '2021 北大光华 431 真题' } ],
    un10: [{ q: R`某人总资产 $250000$ 元，拿出 $200000$ 元买车，车出事故概率为 $5\%$，出事后车价降为 $40000$ 元；效用函数 $U(W)=W^{1/2}$。(1) 判断其风险态度；(2) 求补偿全部损失的完全保险愿意支付的最高价格；(3) 求公平保险价格；(4) 保险市场是否存在交易可能？`,
      a: R`(1) $u''(W)=-\dfrac{1}{4}W^{-3/2}<0$，风险厌恶。(2) 不投保期望效用 $EU=0.95\sqrt{250000}+0.05\sqrt{90000}=0.95\times500+0.05\times300=490$。最高价 $P$ 使 $\sqrt{250000-P}=490\Rightarrow 250000-P=240100\Rightarrow P=9900$ 元。(3) 公平保险价 $=$ 期望赔付 $=5\%\times(200000-40000)=8000$ 元。(4) 最高愿付 $9900>$ 公平价 $8000$，差额即风险溢价 $1900$ 元（$=E(W)-CE=242000-240100$）。故保险公司可在 $(8000,9900)$ 之间定价，双方均受益，存在交易空间。`,
      src: '2015 北大光华 431 真题' },
    { q: R`农民有 $10000$ 元资金，年初买水稻种子 $s$（价格 $p=1$ 元/公斤）和保险 $i$（价格 $q=2$ 元/份，每份赔付 1 公斤大米）。天气好（概率 $\pi=0.8$）时消费 $C_1=10\sqrt{s}$，天气不好绝收、消费完全来自理赔 $C_2=i$。(1) 效用 $U=\pi\log C_1+(1-\pi)\log C_2$，买多少种子、多少保险？(2) 效用 $U=\min\{\log C_1,\log C_2\}$，买多少种子？`,
      a: R`(1) 预算 $s+2i=10000$。最大化 $0.8\log(10\sqrt{s})+0.2\log i$，一阶条件 $\frac{0.4}{s}=\frac{0.1}{i}\Rightarrow s=4i$，代入预算 $6i=10000$，得 $$i=\frac{5000}{3}\approx1667,\qquad s=\frac{20000}{3}\approx6667$$ (2) $\min\{\log C_1,\log C_2\}$ 最优需 $\log C_1=\log C_2$，即 $C_1=C_2$，$10\sqrt{s}=i$。代入预算 $s+2(10\sqrt{s})=10000$，令 $u=\sqrt{s}$：$$u^2+20u-10000=0\Rightarrow u=-10+10\sqrt{101}\approx90.5$$ 故 $$s=u^2\approx8190$$（完全互补型跨期偏好要求两状态消费相等，种子投入更多）。`,
      src: '2017 北大光华 431 真题' } ],
    un11: { q: R`小贩同时卖冰淇淋与汽水，未来一周高温与气温正常概率各 $50\%$，效用 $u(w)=w^{0.5}$。全部卖冰淇淋：高温收入 $2500$、正常 $400$；全部卖汽水：高温 $1600$、正常 $900$。(1) 求使期望效用最大的冰淇淋比例 $\alpha$ 与汽水比例 $1-\alpha$；(2) 保险公司给只卖冰淇淋者设保险：保费每周 $400$，气温正常时赔付 $800$。小贩应买保险只卖冰淇淋，还是不买保险、保持 (1) 的组合？`,
      a: R`(1) 高温财富 $W_h=2500\alpha+1600(1-\alpha)=1600+900\alpha$；正常财富 $W_n=400\alpha+900(1-\alpha)=900-500\alpha$。$$EU=0.5\sqrt{1600+900\alpha}+0.5\sqrt{900-500\alpha}$$ 令 $\frac{dEU}{d\alpha}=0$：$$\frac{450}{\sqrt{1600+900\alpha}}=\frac{250}{\sqrt{900-500\alpha}}$$ 解得 $$\alpha=\frac{1316}{2520}\approx0.522$$ 此时 $EU\approx35.39$。(2) 只卖冰淇淋且投保：高温 $2500-400=2100$，正常 $400-400+800=800$，$$EU=0.5\sqrt{2100}+0.5\sqrt{800}\approx37.05$$ $37.05>35.39$，故应买保险并只卖冰淇淋（保险摊平了两状态收入，风险厌恶者受益）。`,
      src: '2020 北大光华 431 真题' },
    un12: { q: R`圣彼得堡悖论`,
      a: R`期望值为无穷的赌局人们只愿付有限价格（用期望效用评价）。` },
    un13: { q: R`一阶随机占优 FSD`,
      a: R`若对任意 $x$ 有 $F_{A}(x)\le F_{B}(x)$，则 $A$ 一阶随机占优于 $B$。` },
    un14: [{ q: R`风险资产的期望收益与方差`,
      a: R`$$E(r)=\sum p_{i}r_{i},\quad \sigma^{2}=\sum p_{i}(r_{i}-E(r))^{2}$$` },
    { q: R`（2022 真题）每投资 1 元于风险资产 $X$：牛市回报 $R_{X}^{1}=1.5$、熊市 $R_{X}^{2}=0.9$（各 50% 概率）。求 $X$ 的期望收益与方差。`,
      a: R`$$E(R_{X})=\frac{1.5+0.9}{2}=1.2$$ $$\mathrm{Var}(R_{X})=\frac{(1.5-1.2)^{2}+(0.9-1.2)^{2}}{2}=0.09$$ 投资 10 元时 $E(W_{1})=12$、$\mathrm{Var}(W_{1})=100\times0.09=9$。`,
      src: '2022 北大光华 431 真题' } ],
    un15: { q: R`投资者有 10 元，可投两个风险资产 $X,Y$，牛市熊市各 50% 概率。每投 1 元于 $X$：牛市回报 $R_{X}^{1}=1.5$、熊市 $R_{X}^{2}=0.9$；每投 1 元于 $Y$：牛市 $R_{Y}^{1}=0.6$、熊市 $R_{Y}^{2}=2.0$。效用 $U=E(W_{1})-\gamma\,\mathrm{Var}(W_{1})$，$\gamma=0.1$，$W_{1}$ 为总回报。(1) 只能选一个资产，选哪个、效用多少？(2) 若可把比例 $\alpha$ 投 $X$、$1-\alpha$ 投 $Y$，求最优 $\alpha$。`,
      a: R`(1) $X$：$E(R_{X})=\dfrac{1.5+0.9}{2}=1.2$，$\mathrm{Var}(R_{X})=\dfrac{(1.5-1.2)^{2}+(0.9-1.2)^{2}}{2}=0.09$，$E(W_{1})=12$，$\mathrm{Var}(W_{1})=100\times0.09=9$，$U_{X}=12-0.9=11.1$。$Y$：$E(R_{Y})=\dfrac{0.6+2.0}{2}=1.3$，$\mathrm{Var}(R_{Y})=0.49$，$U_{Y}=13-4.9=8.1$。故选 $X$（$11.1>8.1$）。(2) 两状态收益率完全负相关（$\mathrm{Cov}=-0.21$，相关系数 $-1$）。$E(W_{1})=10[\alpha\times1.2+(1-\alpha)\times1.3]=13-\alpha$；$\mathrm{Var}(W_{1})=100\left[0.09\alpha^{2}+0.49(1-\alpha)^{2}-0.42\alpha(1-\alpha)\right]=100(\alpha-0.7)^{2}$。故 $U=13-\alpha-10(\alpha-0.7)^{2}$，令 $\dfrac{dU}{d\alpha}=13-20\alpha=0\Rightarrow\alpha=0.65$。即 65% 投 $X$、35% 投 $Y$。`,
      src: '2022 北大光华 431 真题' },
    un16: { q: R`淘金者挖到价值 $w$ 的金子，朋友免费帮运回城，但途中有概率 $p$ 被偷、$(1-p)$ 安全到达。淘金者风险厌恶，效用 $u(w)$。方案一：一次性运输；方案二：分两次各运一半（两次被偷事件独立）。(1) 写出两方案的状态、概率与财富；(2) 风险厌恶者会选哪种？请证明。`,
      a: R`(1) 方案一：财富 $w$（概率 $1-p$）或 $0$（概率 $p$），期望 $(1-p)w$。方案二：全到 $w$（$(1-p)^2$）、一半被偷 $w/2$（$2p(1-p)$）、全被偷 $0$（$p^2$），期望 $(1-p)^2w+2p(1-p)\cdot\frac w2=(1-p)w$，与方案一相同。(2) 两方案均值相同，但方案二方差更小：$Var_1=w^2p(1-p)$，$Var_2=\frac{w^2p(1-p)}{2}=\frac{Var_1}{2}$。风险厌恶者（$u''<0$）偏好同均值下方差更小的分布（方案二二阶随机占优于方案一），故选分两次运输——分散化降低了风险。`,
      src: '2014 北大光华 431 真题' },
    wf01: { q: R`一般均衡的含义`,
      a: R`所有市场同时达到供求相等的状态。` },
    wf07: { q: R`边际转换率 MRT`,
      a: R`$$MRT_{XY}=-\frac{dY}{dX}=\frac{MC_{X}}{MC_{Y}}$$` },
    wf08: { q: R`契约曲线的含义`,
      a: R`埃奇沃斯盒中所有帕累托最优点（无差异曲线相切点）的轨迹。` },
    wf13: { q: R`生产可能性边界（PPF）`,
      a: R`既定资源与技术下两产品最大产量组合，凹向原点。` },
    wf15: { q: R`瓦尔拉斯（竞争）均衡`,
      a: R`存在一组价格使所有市场超额需求为零。` },
    wf16: { q: R`超额需求函数`,
      a: R`$$z_{i}(p)=x_{i}(p)-e_{i}(p)$$` },
    wf17: { q: R`瓦尔拉斯法则`,
      a: R`$$p\cdot z(p)=\sum p_{i}z_{i}(p)=0$$` },
    wf18: { q: R`两种商品 $x,y$。小丽效用 $u=x+y$，小贾效用 $u=\max\{x,y\}$。(1) 用无差异曲线在埃奇沃斯盒中画出两人偏好；(2) 猜想均衡价格关系；(3) 猜想均衡分配结果。`,
      a: R`(1) 小丽 $u=x+y$：无差异曲线为斜率 $-1$ 的直线（完全替代）。小贾 $u=\max\{x,y\}$：无差异曲线为沿两轴的直角折线（$x=y$ 处折角），偏好集非凸。(2) 小丽的 $MRS_{xy}=1$ 恒定，要有内点解需 $\frac{p_x}{p_y}=1$，故猜想均衡价格 $p_x=p_y$。(3) 给定 $p_x=p_y$，小贾在 $x=y$ 折角处或任一轴上无差异（他只要"两种商品中较多的一种"），均衡时小贾消费等量的 $(x,x)$，小丽消费预算线上其余部分（沿直线 $x+y$ 分配）。因小贾偏好非凸，需注意瓦尔拉斯均衡的存在性与福利定理的凸性前提。`,
      src: '2018 北大光华 431 真题' },
    wf19: { q: R`契约曲线的求解方法`,
      a: R`令 $MRS^{A}=MRS^{B}$ 解出消费量关系。` },
    wf20: { q: R`比较优势`,
      a: R`一国在某产品上机会成本较低则具有比较优势。` },
    wf21: { q: R`国际贸易的收益`,
      a: R`按比较优势分工贸易，使消费超出各自生产可能性边界。` },
    pd23: { q: R`生产可能性边界的斜率`,
      a: R`$$MRT=-\frac{dY}{dX}$$` },
    mk17: { q: R`寡头市场的特征`,
      a: R`少数厂商相互依存、相互影响。` },
    mk19: [{ q: R`古诺均衡总产量与价格（双寡头）`,
      a: R`$$Q=\frac{2(a-c)}{3b},\quad P=\frac{a+2c}{3}$$` },
    { q: R`（2023 真题）双寡头需求 $P(q_{1},q_{2})=9-q_{1}-q_{2}$，边际成本 $C_{1}=C_{2}=3$。求古诺均衡产量与价格。`,
      a: R`对称古诺公式（$a=9,\ b=1,\ c=3$）：$$q_{1}=q_{2}=\frac{a-c}{3b}=\frac{9-3}{3}=2,\qquad Q=q_{1}+q_{2}=4$$ $$P=\frac{a+2c}{3}=\frac{9+6}{3}=5$$ 验证：$P=9-4=5$，每家利润 $(5-3)\times2=4$。`,
      src: '2023 北大光华 431 真题' } ],
    mk22: [{ q: R`卡特尔的利润最大化条件`,
      a: R`$$MR=MC_{1}=MC_{2}$$（按边际成本分配产量）` },
    { q: R`（2024 真题）4 个同质厂商（边际成本均为 10）合谋追求利润最大化，代表性消费者购买 $x$ 单位的效用为 $20x-5x^{2}$（逆需求 $P=20-10Q$）。求卡特尔的总产量与价格。`,
      a: R`卡特尔整体利润 $$\Pi=(20-10Q)Q-10Q=10Q-10Q^{2}$$ 令 $\frac{d\Pi}{dQ}=10-20Q=0\Rightarrow Q=\frac12$，价格 $P=20-10\times\frac12=15$。卡特尔按整体 $MR=MC$ 定产（成员再按边际成本分配产量），产量低于古诺（$\frac45$）、价格更高。`,
      src: '2024 北大光华 431 真题' } ],
    mk23: { q: R`两厂商产品有差异但可替代，同时定产。厂商 1 逆需求 $p_1=100-2q_1-q_2$，成本 $C_1=\tfrac12 q_1^2$；厂商 2 逆需求 $p_2=100-q_1-\beta q_2$（$\beta>1$），成本 $C_2=q_2$。(1)(2) 求两厂商的反应函数与均衡产量；(3) 厂商 2 在何条件下停产？`,
      a: R`(1) 厂商 1：$\pi_1=(100-2q_1-q_2)q_1-\tfrac12 q_1^2$，一阶条件 $100-5q_1-q_2=0$，反应函数 $$q_1=\frac{100-q_2}{5}$$ (2) 厂商 2：$\pi_2=(100-q_1-\beta q_2)q_2-q_2=(99-q_1-\beta q_2)q_2$，一阶条件 $99-q_1-2\beta q_2=0$，反应函数 $$q_2=\frac{99-q_1}{2\beta}$$ 联立解得 $$q_1=\frac{200\beta-99}{10\beta-1},\qquad q_2=\frac{99-q_1}{2\beta}$$ (3) 厂商 2 停产即 $q_2=0\Leftrightarrow q_1\ge99$，但均衡 $q_1=\frac{200\beta-99}{10\beta-1}<20$（$\beta>1$），故 $\beta>1$ 下厂商 2 恒为正产量、不会退出；差异化古诺通过反应函数交点确定，$\beta$ 越大厂商 2 需求越缺乏弹性、其产量越低。`,
      src: '2022 北大光华 431 真题' },
    mk24: { q: R`赫芬达尔指数 HHI`,
      a: R`$$HHI=\sum_{i}s_{i}^{2}$$` },
    mk25: { q: R`行业集中度 CRn`,
      a: R`前 $n$ 家最大厂商市场份额之和。` },
    mk31: [{ q: R`某种只有固定成本（边际成本为 0）的生产活动中，四个寡头厂商面临市场需求 $P=100-Q$。在古诺模型下，求每厂商的均衡产量、总产量与价格。`,
      a: R`由 $n$ 厂商古诺公式 $$q_{i}=\frac{a-c}{(n+1)b}=\frac{100-0}{5\times1}=20$$，四厂商各生产 $20$。总产量 $$Q=4\times20=80$$，价格 $$P=100-80=20$$。`,
      src: '考研真题（古诺模型·四寡头，$P=100-Q$）' },
    { q: R`4 个生产同质产品的厂商，边际成本均为 $10$；代表性消费者购买 $x$ 单位产品的效用为 $20x-5x^2$。(1) 各厂商独立决策（古诺）时的总供给；(2) 各厂商合谋时的总供给；(3) (1)(2) 的总消费者剩余相差多少？为什么？`,
      a: R`逆需求 $P=MU=20-10x$，即 $P=20-10Q$。(1) 古诺：$\pi_i=(20-10Q)q_i-10q_i$，一阶条件 $1-Q-q_i=0$，对称 $5q_i=1\Rightarrow q_i=0.2$，总供给 $$Q=4\times0.2=0.8,\ P=12$$ (2) 合谋：最大化 $(20-10Q)Q-10Q=10Q-10Q^2$，$10-20Q=0\Rightarrow Q=0.5,\ P=15$。(3) 古诺下 $CS=\int_0^{0.8}(20-10x)dx-12\times0.8=3.2$；合谋下 $CS=\int_0^{0.5}(20-10x)dx-15\times0.5=1.25$。相差 $$3.2-1.25=1.95$$ 合谋限制产量、抬高价格，把消费者剩余转化为垄断利润并造成无谓损失。`,
      src: '2024 北大光华 431 真题' } ],
    mk32: { q: R`卡特尔为何不稳定？`,
      a: R`成员有背叛动机（给定他人限产，自己增产可获利）。` },
    mk33: { q: R`限制性定价`,
      a: R`在位者定价低于垄断价以阻止进入。` },
    mk34: { q: R`上游垄断企业 $U$ 以单价 $p_{u}$ 向垄断下游企业 $D$ 出售中间品，$U$ 生产成本为 0；$D$ 一比一加工后以 $p_{d}$ 卖给消费者，除中间品费用外无其他成本，需求 $q(p_{d})=1-p_{d}$。求：(1) 给定 $p_{u}$，$D$ 的定价；(2) 子博弈精炼均衡的 $p_{u},p_{d}$；(3) 均衡时两企业利润与销量；(4) 若 $U,D$ 合并，销量、利润与消费者福利如何变化？`,
      a: R`(1) $D$ 最大化 $(p_{d}-p_{u})(1-p_{d})$，一阶条件 $1-2p_{d}+p_{u}=0\Rightarrow p_{d}=\dfrac{1+p_{u}}{2}$。(2) $U$ 最大化 $p_{u}\left(1-\dfrac{1+p_{u}}{2}\right)=\dfrac{p_{u}(1-p_{u})}{2}$，一阶条件 $1-2p_{u}=0\Rightarrow p_{u}=\dfrac{1}{2}$，故 $p_{d}=\dfrac{1+1/2}{2}=\dfrac{3}{4}$。(3) 销量 $q=1-\dfrac{3}{4}=\dfrac{1}{4}$；$U$ 利润 $\dfrac{1}{2}\times\dfrac{1}{4}=\dfrac{1}{8}$，$D$ 利润 $\left(\dfrac{3}{4}-\dfrac{1}{2}\right)\times\dfrac{1}{4}=\dfrac{1}{16}$，总利润 $\dfrac{3}{16}$。(4) 合并后单一垄断者最大化 $p_{d}(1-p_{d})$，得 $p_{d}=\dfrac{1}{2},\ q=\dfrac{1}{2}$，利润 $\dfrac{1}{4}$。相比 (3)：价格由 $\dfrac{3}{4}$ 降至 $\dfrac{1}{2}$、销量由 $\dfrac{1}{4}$ 增至 $\dfrac{1}{2}$、总利润由 $\dfrac{3}{16}$ 增至 $\dfrac{1}{4}$，消费者剩余上升——纵向一体化消除了双重加价。`,
      src: '2020 北大光华 431 真题' },
    mk35: { q: R`寡头合谋更易维持的条件`,
      a: R`市场集中、壁垒高、产品同质、信息透明、惩罚可信。` },
    gm10: { q: R`重复博弈的意义`,
      a: R`无限次重复下合作（如针锋相对）可能成为均衡。` },
    gm11: { q: R`零和博弈`,
      a: R`一方所得即另一方所失，支付之和为零。` },
    gm18: [{ q: R`混合策略纳什均衡的求解`,
      a: R`令对手各纯策略期望支付相等，解出最优混合概率。` },
    { q: R`（2025 真题）两个股票投机者同时选择是否卖空：卖空需支付成本 $c=2$、收益 $v=1.5N$（$N$ 为卖空人数），不卖空成本与收益均为 0。求对称混合策略纳什均衡。`,
      a: R`设对手以概率 $q$ 卖空：都卖空（$N=2$）时我方支付 $1.5\times2-2=1$，仅我方卖空（$N=1$）时支付 $1.5-2=-0.5$，故我方卖空的期望支付 $$q\times1+(1-q)\times(-0.5)=1.5q-0.5$$ 不卖空为 $0$。令两者相等：$$1.5q-0.5=0\Rightarrow q=\frac13$$ 对称混合策略纳什均衡为双方各以 $\frac13$ 概率卖空、$\frac23$ 概率不卖空——令对手各纯策略期望支付相等即得混合概率。`,
      src: '2025 北大光华 431 真题' } ],
    gm19: { q: R`演化稳定策略 ESS`,
      a: R`能抵抗任何小规模突变策略入侵的策略。` },
    mk14: { q: R`垄断竞争市场的特征`,
      a: R`厂商多、产品有差异、进出较易。` },
    mk15: { q: R`垄断竞争厂商短期均衡条件`,
      a: R`$$MR=MC$$` },
    mk16: { q: R`垄断竞争厂商长期均衡条件`,
      a: R`$$MR=MC,\quad P=AC$$（零利润，存在过剩产能）` },
    cu34: { q: R`劳动-闲暇选择的预算约束`,
      a: R`$$C=w(\bar{L}-L)+M$$` },
    cu35: { q: R`劳动供给的最优条件`,
      a: R`$$MRS=\frac{MU_{L}}{MU_{C}}=w$$` },
    cu36: { q: R`劳动供给曲线向后弯曲的原因`,
      a: R`工资足够高时收入效应（多闲暇）超过替代效应（多工作）。` },
    rv14: { q: R`要素的边际收益产品 MRP`,
      a: R`$$MRP=MP\cdot MR$$` },
    rv15: [{ q: R`完全竞争下要素需求条件`,
      a: R`$$VMP=MP\cdot P=w$$` },
    { q: R`（2015 真题）生产函数 $f(x_{1},x_{2})=\min\{x_{1},\,x_{2}^{\alpha}\}$（$0<\alpha<1$），要素价格 $w_{1}=10,\ w_{2}=20$，产品价格 $p=50$。求利润最大化时的要素需求函数。`,
      a: R`有效生产 $x_{1}=x_{2}^{\alpha}$，利润 $$\pi=50x_{2}^{\alpha}-10x_{2}^{\alpha}-20x_{2}=40x_{2}^{\alpha}-20x_{2}$$ 一阶条件 $$40\alpha x_{2}^{\alpha-1}=20\Rightarrow x_{2}^{*}=(2\alpha)^{1/(1-\alpha)},\qquad x_{1}^{*}=(2\alpha)^{\alpha/(1-\alpha)}$$ 要素使用至其边际产品价值等于要素价格，即得要素需求函数。`,
      src: '2015 北大光华 431 真题' } ],
    rv16: { q: R`要素使用的最优条件`,
      a: R`$$MRP=w$$` },
    mk28: { q: R`卖方垄断下的要素使用条件`,
      a: R`$$MRP=MP\cdot MR=w$$` },
    mk29: { q: R`买方垄断（垄断买主）的要素使用条件`,
      a: R`$$VMP=MP\cdot P=MFC$$` },
    fl01: [{ q: R`市场失灵的主要原因`,
      a: R`外部性、公共物品、垄断、信息不对称。` },
    { q: R`（2014 真题）某海湾盛产龙虾：有 $x$ 艘捕虾船时总收入 $f(x)=1000x(1-0.2x)$，经营一艘船每月花费 200。(1) 求最大化总利润的船只数；(2) 若每个村民都有捕虾权（自由进入），会有多少艘船进入、利润如何？并说明为何 (2) 的结果无效率（市场失灵）。`,
      a: R`(1) 总利润 $\pi=f(x)-200x=800x-200x^{2}$，$\pi'=800-400x=0\Rightarrow x=2$，利润 $800$。(2) 自由进入时每船利润趋零：每船收入 $\dfrac{f(x)}{x}=1000(1-0.2x)=200\Rightarrow x=4$，总利润 $0$。自由进入（4 艘）超过社会最优（2 艘）——捕虾权公有，无人承担多捕对他人的损失（负外部性），公共资源被过度使用，属市场失灵；村委会发放许可证即可恢复效率。`,
      src: '2014 北大光华 431 真题' } ],
    fl02: [{ q: R`外部性的定义`,
      a: R`行为影响他人福利而未通过市场价格得到补偿或支付。` },
    { q: R`（2013 真题）电影院利润 $\pi_{C}=48Y-Y^{2}$（$Y$ 为电影院数），肯德基利润 $\pi_{K}=60X-X^{2}+XY$（$X$ 为肯德基数）。指出该例中的外部性类型与方向。`,
      a: R`肯德基利润含 $+XY$ 项：电影院每多开一家，肯德基利润增加 $X$（$\dfrac{\partial\pi_{K}}{\partial Y}=X>0$），电影院的行为改善了肯德基的福利却未获任何补偿——这是电影院对肯德基的**正外部性**。外部性即行为影响他人福利而未通过市场价格得到补偿或支付。`,
      src: '2013 北大光华 431 真题' } ],
    fl03: [{ q: R`负外部性下社会边际成本`,
      a: R`$$\text{社会边际成本}=\text{私人边际成本}+\text{外部边际成本}$$` },
    { q: R`（2016 真题）完全竞争钢铁市场：需求 $Q^{d}=20-P$，供给（私人边际成本）$P^{s}=2+Q$，污染边际损耗 $MD=0.5Q$。写出社会边际成本曲线，并求社会最优产量。`,
      a: R`社会边际成本 $=$ 私人边际成本 $+$ 外部边际成本：$$SMC=2+Q+0.5Q=2+1.5Q$$ 令 $SMC$ 与需求相等：$$20-Q=2+1.5Q\Rightarrow Q^{*}=7.2$$ 社会最优产量低于私人均衡产量（$Q=9$）。`,
      src: '2016 北大光华 431 真题' } ],
    fl04: [{ q: R`负外部性的后果`,
      a: R`私人产量高于社会最优（过度生产）。` },
    { q: R`（2020 真题）A、B 企业生产函数 $y_{a}=2(L_{a})^{0.5}$、$y_{b}=(L_{b})^{0.5}$，产品价格 $p=30$、工资 $w=5$，排污量 $v_{a}=(y_{a})^{2}$、$v_{b}=(y_{b})^{2}$。(1) 求使居民效用 $8(L_{a}+L_{b})^{0.5}-(v_{a}+v_{b})$ 最大化的社会最优排污；(2) 求企业无视污染时的总排污量。`,
      a: R`(1) $v_{a}=(2\sqrt{L_{a}})^{2}=4L_{a}$、$v_{b}=L_{b}$，最大化 $8\sqrt{L_{a}+L_{b}}-4L_{a}-L_{b}$。B 的排污社会成本低，最优全部由 B 承担：$\frac{4}{\sqrt{L_{b}}}=1\Rightarrow L_{b}=16$，故 $v_{a}=0,\ v_{b}=16$。(2) 企业按 $VMP=w$ 雇佣：$L_{a}=36\Rightarrow v_{a}=144$；$L_{b}=9\Rightarrow v_{b}=9$，总排污 $153$。私人排污（$153$）远高于社会最优（$16$）——负外部性导致过度生产（过度排污）。`,
      src: '2020 北大光华 431 真题' } ],
    fl05: { q: R`尽管单场马拉松比赛的综合收益往往亏损，为何各地政府仍热衷举办马拉松？国家有关部门为何又加强监管、给马拉松"降温"？`,
      a: R`(1) 举办马拉松具有**正外部性**：虽赛事本身账面上亏损，但带动旅游、餐饮、住宿、城市品牌宣传、全民健身等社会收益，这些外部收益未计入主办方收益，故地方政府从城市总福利出发仍愿意举办。(2) 加强监管的原因是**负外部性**：大规模赛事造成交通管制拥堵、安全隐患、资源浪费、扰民与公共支出负担，且各地盲目跟风导致过度供给；当边际社会成本超过边际社会收益时，就需要规制"降温"，使举办数量回到社会最优水平。`,
      src: '2026 北大光华 431 真题' },
    fl06: [{ q: R`完全竞争钢铁市场需求 $Q^{d}=20-P$、供给（私人边际成本）$P^{s}=2+Q$；炼钢污染边际损耗 $MD=0.5Q$。(1) 无干预时市场均衡价格与产量？(2) 社会最优产量及污染成本？(3) 外部性造成的社会福利损失？(4) 政府如何通过产量税达到社会最优？`,
      a: R`(1) $20-Q=2+Q\Rightarrow Q=9,\ P=11$。(2) 社会边际成本 $=2+Q+0.5Q=2+1.5Q$，令 $20-Q=2+1.5Q\Rightarrow Q^{*}=7.2$；边际损耗 $MD(Q^{*})=0.5\times7.2=3.6$，总污染成本 $\int_{0}^{7.2}0.5q\,dq=0.25\times7.2^{2}=12.96$。(3) 无谓损失 $=\dfrac{1}{2}\times MD(9)\times(9-7.2)=\dfrac{1}{2}\times4.5\times1.8=4.05$。(4) 庇古税 $t=MD(Q^{*})=3.6$（每单位产量征税 3.6）。征税后私人边际成本变为 $2+Q+3.6=5.6+Q$，令 $20-Q=5.6+Q\Rightarrow Q=7.2=Q^{*}$，恰好实现社会最优。`,
      src: '2016 北大光华 431 真题' },
    { q: R`城市 W 由两座火电厂 A、B 供电，减排会排放污染。A 减排 $x_A$ 万吨成本 $C_A=3x_A^2$，B 减排 $x_B$ 万吨成本 $C_B=5x_B^2+10x_B$；减排给全市带来的总收益为 $120(x_A+x_B)$。(1) 求社会最优减排量；(2) 政府对每万吨污染物征排污税 $t$，求 $t$ 使两厂达到社会最优，并写出各厂优化问题、证明其最优减排量与社会最优一致；(3) 论证"强制 A、B 各减排 1 万吨"并非最有效率。`,
      a: R`(1) 最大化 $120(x_A+x_B)-3x_A^2-5x_B^2-10x_B$：$$\frac{\partial}{\partial x_A}:120-6x_A=0\Rightarrow x_A=20;\qquad \frac{\partial}{\partial x_B}:120-10x_B-10=0\Rightarrow x_B=11$$ (2) 征排污税 $t$ 后，A 最小化 $3x_A^2-tx_A$，一阶条件 $6x_A=t$，令 $x_A=20$ 得 $t=120$；B 最小化 $5x_B^2+10x_B-tx_B$，一阶条件 $10x_B+10=t$，令 $x_B=11$ 得 $t=120$。故每万吨征税 $t=120$ 时，两厂分别解得 $x_A=20,\ x_B=11$，恰为社会最优——庇古税把外部收益内部化。(3) 强制各减排 1 万吨时，A 边际减排成本 $6\times1=6$、B 边际成本 $10\times1+10=20$，二者不相等且总减排量（2 万吨）远低于社会最优（31 万吨）；均摊减排未按边际成本分配减排任务，故无效率。`,
      src: '2017 北大光华 431 真题' } ],
    fl07: { q: R`肯德基开店量 $X$、电影院开店量 $Y$，电影院对肯德基有正外部性。电影院利润 $\pi_{C}=48Y-Y^{2}$，肯德基利润 $\pi_{K}=60X-X^{2}+XY$。(1) 求二者独立决策时的最优开店量 $X,Y$ 及各自利润；(2) 若肯德基收购电影院联合决策，求最优开店量及总利润；(3) 若仍独立决策，但肯德基承诺每开一家电影院补贴 $S$ 万元，求最佳开店量。`,
      a: R`(1) 独立决策：电影院 $$\frac{\partial\pi_{C}}{\partial Y}=48-2Y=0\Rightarrow Y=24$$；肯德基 $$\frac{\partial\pi_{K}}{\partial X}=60-2X+Y=0\Rightarrow X=\frac{60+Y}{2}=42$$。故 $X=42,\ Y=24$，$$\pi_{C}=48\times24-24^{2}=576,\qquad \pi_{K}=60\times42-42^{2}+42\times24=1764$$。(2) 合并后最大化 $$\Pi=48Y-Y^{2}+60X-X^{2}+XY$$，由 $$\begin{cases}60-2X+Y=0\\ 48-2Y+X=0\end{cases}$$ 解得 $X=56,\ Y=52$，总利润 $2928$（电影院自身利润为负 $48\times52-52^{2}=-208$，但被内部化）。独立决策总利润 $576+1764=2340<2928$，合并提高总利润。(3) 补贴后电影院利润 $$\pi_{C}=48Y-Y^{2}+SY$$，令 $$48-2Y+S=0\Rightarrow S=2Y-48$$，要使 $Y$ 达到联合最优 $52$，$$S=2\times52-48=56=X^{*}$$，即补贴额等于边际外部收益 $X$。`,
      a2: R`💡 巧解（内部化·边际外部收益）：肯德基对电影院的边际外部收益为 $\dfrac{\partial\pi_K}{\partial Y}=X$，在社会最优 $X^{*}=56$ 处恰为 $56$。故最优补贴直接取 $$S^{*}=\frac{\partial\pi_K}{\partial Y}\Big|_{(X^{*},Y^{*})}=56$$ 无需重解电影院的一阶条件——补贴额=社会最优处的边际外部收益。`,
      src: '2013 年北大光华 431 真题' },
    fl08: { q: R`科斯定理`,
      a: R`产权明确且交易成本为零时，自愿协商可实现帕累托最优。` },
    fl09: { q: R`公共物品的两个特征`,
      a: R`非竞争性与非排他性。` },
    fl10: [{ q: R`某村有 $n$ 个村民、一笔财富 $w$，在其中 $k$ 个村民中平均分配（$k\le n$）。分到钱者决定用多少修路、多少私人消费。修路 $H=\sum_{i=1}^{k}h_{i}$ 全村受益，效用 $U_{i}=H^{1/2}X_{i}^{1/2}$（$X_{i}$ 私人消费），公路与私人消费品价格均为 1。(1) 求均衡（各自独立决策）下总修路长度；(2) 求社会最优修路长度，并说明其随 $k$ 如何变化。`,
      a: R`(1) 每人预算 $h_{i}+X_{i}=\dfrac{w}{k}$，最大化 $U_{i}$（视 $H$ 给定）：$\dfrac{\partial U_{i}}{\partial h_{i}}=\dfrac{1}{2}H^{-1/2}X_{i}^{1/2}-\dfrac{1}{2}H^{1/2}X_{i}^{-1/2}=0\Rightarrow X_{i}=H$。故 $h_{i}=\dfrac{w}{k}-H$，加总 $H=\sum h_{i}=w-kH\Rightarrow H=\dfrac{w}{k+1}$，每户 $h_{i}=\dfrac{w}{(k+1)^{2}}$。(2) 社会最优满足萨缪尔森条件 $\sum_{i}MRS_{i}=MRT=1$，其中 $MRS_{i}=\dfrac{MU_{H}}{MU_{X}}=\dfrac{X_{i}}{H}$，故 $\sum X_{i}=H$。由资源约束 $\sum X_{i}+H=w$ 得 $H^{*}=\dfrac{w}{2}$，每户 $h_{i}^{*}=\dfrac{w}{2k}$。$H^{*}=\dfrac{w}{2}$ 与 $k$ 无关，而均衡 $H=\dfrac{w}{k+1}$ 随 $k$ 增大而减小——受益者越多，搭便车越严重，公共物品供给越不足（$H<H^{*}$，且 $k$ 越大缺口越大）。`,
      src: '2014 北大光华 431 真题' },
    { q: R`某市新建音乐会场地，两居民小丽（收入 200）与小贾（收入 100）捐赠座位，效用 $U_i(X_i,S)=0.5\ln X_i+0.5\ln S$，总座位 $S=S_L+S_J$，私有品与座位单价均为 1。(1) 无干预时建造多少座位、各由谁捐多少？(2) 社会最优座位数，与 (1) 不同的原因；(3) 座位价格变 $P_S$ 时每人预算增加 $C_i=(P_S-1)S_i$（补偿预算），写出该约束并解释；(4) 通过需求纵向加总求社会最优。`,
      a: R`(1) 每人最大化 $0.5\ln X_i+0.5\ln(S_i+S_{-i})$，一阶条件 $\frac{1}{S}=\frac{1}{X_i}\Rightarrow X_i=S$（个人把总座位视为给定）。小丽 $S_L=200-S$、小贾 $S_J=100-S$，$S=S_L+S_J=300-2S\Rightarrow S=100$，即小丽捐 $100$、小贾捐 $0$（完全搭便车）。(2) 社会最大化 $0.5\ln X_L+0.5\ln X_J+\ln S$，s.t. $X_L+X_J+S=300$：由 $\frac{0.5}{X_L}=\frac{0.5}{X_J}=\frac{1}{S}$ 得 $X_L=X_J=S/2$，$2S=300\Rightarrow S^*=150>100$——公共物品的搭便车导致供给不足。(3) 补偿预算 $X_i+P_SS_i=I_i+(P_S-1)S_i\Leftrightarrow X_i+S_i=I_i$，即价格变动时补偿使原消费束仍可负担（斯勒茨基式补偿）。(4) 林达尔解法：纵向加总各人的逆需求（边际支付意愿），令 $\sum_i P_S^i=MC=1$，解得 $S^*=150$，与 (2) 一致。`,
      src: '2018 北大光华 431 真题' } ],
    fl11: [{ q: R`搭便车问题`,
      a: R`因非排他，个人隐瞒偏好不付费，导致供给不足。` },
    { q: R`（2023 真题）两消费者效用 $U_{i}=\sqrt{g\,C_{i}}$（$i=1,2$），财富 $W_{i}$ 分配于公共品 $g_{i}$ 与私人消费 $C_{i}$，总公共品 $g=g_{1}+g_{2}$。若每人独立决策，求均衡的公共品总量 $g$，并与政府统一决策的社会最优比较。`,
      a: R`独立决策（搭便车）：每人把 $g$ 视为给定，最大化 $\sqrt{g\,C_{i}}$ s.t. $g_{i}+C_{i}=W_{i}$，解得反应函数 $g_{i}=\frac{W_{i}-g_{-i}}{2}$，加总得 $$g=\frac{W_{1}+W_{2}}{3}$$ 而社会最优（萨缪尔森条件 $\sum MRS_{i}=1$）为 $$g^{*}=\frac{W_{1}+W_{2}}{2}$$ 均衡供给 $g<g^{*}$，且总效用 $\frac23(W_{1}+W_{2})<\frac{\sqrt2}{2}(W_{1}+W_{2})$——公共品非排他使个人不愿出资，搭便车导致供给不足。`,
      src: '2023 北大光华 431 真题' } ],
    wf22: { q: R`林达尔均衡`,
      a: R`个人按其边际支付意愿分担成本，使供给满足所有人需求。` },
    fl12: [{ q: R`公司需投资 100 运行新项目，项目净现值 $b$，当前固定资产总值 $a$，需向公众股权融资。公司可能处于两种状态（概率各 50%，只有公司知道）：状态一 $a=400,\ b=30$；状态二 $a=100,\ b=10$。投资者风险中性。(1) 若公司无论如何都股权融资，市场定价（公司价值）应为多少？(2) 状态一与状态二的公司各会选择股权融资吗？解释原因。`,
      a: R`(1) 项目投产后公司价值 $=a+100+b$：状态一 $530$、状态二 $210$，市场按期望定价 $=\dfrac{1}{2}\times530+\dfrac{1}{2}\times210=370$。融资 100 元对应出让股份比例 $\dfrac{100}{370}\approx27\%$。(2) 状态一（真实价值 530）按 370 定价被低估：融资后老股东保留 $(1-\dfrac{100}{370})\times530\approx386.7$，低于不融资保留的 $400$，故不愿发股。状态二（真实价值 210）被高估：保留 $(1-\dfrac{100}{370})\times210\approx153.2$，高于不融资保留的 $100$，故愿意发股。故优质公司被低估而退出、劣质公司被高估而融资，属逆向选择（柠檬市场）。`,
      src: '2024 北大光华 431 真题' },
    { q: R`企业家向银行申请 100 万贷款投资，项目成功概率 $q$（$q=\tfrac23$ 或 $\tfrac12$ 各 $50\%$，企业家自知、银行不知），成功收益 300 万、失败为 0。银行要求项目成功时偿还 $F$ 以维持收支平衡（预期还款 = 100 万）。(1) 求 $F$；(2) 企业家还可另投一个确定收益 220 万的项目（投 100 万必得 220 万），企业家贷款后选预期收益更大的项目，求银行收支平衡的 $F$ 最小值。`,
      a: R`(1) 两类企业家都借款，银行预期还款 $E[q]\cdot F=\left(\tfrac12\cdot\tfrac23+\tfrac12\cdot\tfrac12\right)F=\tfrac{7}{12}F=100$，故 $$F=\frac{1200}{7}\approx171.43$$ (2) 企业家做风险项目需 $q(300-F)>220-F\Rightarrow F>\frac{220-300q}{1-q}$：对 $q=\tfrac12$ 需 $F>140$，对 $q=\tfrac23$ 需 $F>60$。分区间求银行收支平衡：$F\le60$ 时两类都选确定项目、还款 $F$ 必得，$F=100$ 矛盾；$60<F\le140$ 时高质量做风险、低质量做确定项目，预期还款 $\tfrac12 F+\tfrac12\cdot\tfrac23 F=\tfrac56 F=100\Rightarrow F=120$；$F>140$ 时两类都做风险，$F=1200/7\approx171.43$。故收支平衡的最小 $F=120$（逆向选择下利率抬升、好项目被"挤出"）。`,
      src: '2025 北大光华 431 真题' } ],
    fl13: [{ q: R`道德风险`,
      a: R`签约后一方因信息不对称改变行为、增加风险（事后）。` },
    { q: R`（2021 真题）两雇员工资均为 $M$，各以 50% 概率被解雇（被裁者收入 0），二人可签风险共担契约（无论谁被裁都与对方平分收入 $M/2$）。签约后双方都担心对方不守信用、事后不履行契约，于是请律师把契约写成可执行合同。结合道德风险概念说明为何需要可执行合同。`,
      a: R`风险共担契约签订后，任何一方都有事后违约（不履行平分承诺）的动机——签约后因信息不对称改变行为、增加对方风险，正是**道德风险**（事后机会主义）。故需付律师费把契约写成可执行合同、由违约方支付补偿金 $T$ 保证两人收入相等，使承诺可置信。`,
      src: '2021 北大光华 431 真题' } ],
    fl14: [{ q: R`柠檬市场`,
      a: R`买者信息不足压低出价，市场萎缩或消失。` },
    { q: R`（2026 真题）请从价格歧视、道德风险、逆向选择、沉没成本、外部性五个概念中，指出哪些与企业上市 IPO 定价过程密切相关，并解释原因。`,
      a: R`与 IPO 定价密切相关的是**逆向选择**与**道德风险**（信息不对称）：(1) 逆向选择——发行企业比投资者更了解自身价值，投资者因信息不足压低发行价，优质企业被低估（柠檬市场、IPO 抑价）；(2) 道德风险——上市融资后资金使用与管理层努力难以监督，投资者要求折价补偿。沉没成本（承销费用）与外部性关系较弱。`,
      src: '2026 北大光华 431 真题' } ],
    fl15: { q: R`应对信息不对称的机制`,
      a: R`信号传递与信息甄别。` },
    gm14: { q: R`小李先行动选 $H$ 或 $L$，小王看不到小李的行动，只能收到信号 $h$ 或 $l$，且 $Pr(h|H)=p,\ Pr(l|H)=1-p,\ Pr(h|L)=q,\ Pr(l|L)=1-q$，其中 $p>0.5>q$。小王在观测信号后选 $A$ 或 $B$，支付矩阵：$(H,A)=(5,2),\ (H,B)=(2,1),\ (L,A)=(6,1),\ (L,B)=(4,2)$（前为小李收益）。(1) $p=1,q=0$ 时列出小王的所有策略与收益矩阵，求纯策略纳什均衡；(2) $p<1,q>0$ 时小王有多少种纯策略？`,
      a: R`(1) 小王策略是"信号→行动"的映射，共 $2^2=4$ 种：$AA$（$h\to A,l\to A$）、$AB$、$BA$、$BB$。$p=1,q=0$ 时信号完全揭示行动（$h\Rightarrow H,\ l\Rightarrow L$）。小李比较：选 $H$ 时小王最优反应是 $A$（得 $2>1$），选 $L$ 时小王最优反应是 $B$（得 $2>1$）；而小李在 $(H,A)=(5)$、$(L,B)=(4)$ 之间选 $H$。故均衡为：小李选 $H$，小王策略 $h\to A,\ l\to B$（即 $AB$），支付 $(5,2)$——信号精确时均衡与完全信息序贯博弈一致。(2) $p<1,q>0$ 时信号有噪声，小王策略仍是 $h,l$ 到 $\{A,B\}$ 的映射，共 4 种纯策略，但需按贝叶斯信念（$Pr(H|h)=\frac{p}{p+q}$ 等）计算期望支付再求最优。`,
      src: '2015 北大光华 431 真题' },
    gm15: { q: R`四种基本拍卖形式`,
      a: R`英式、荷式、密封第一价格、密封第二价格（维克里）。` },
    gm16: { q: R`维克里（第二价格）拍卖`,
      a: R`报真实估价是占优策略，成交价等于第二高报价。` },
    gm17: { q: R`收益等价定理`,
      a: R`对称、独立私人价值、风险中性下，四种拍卖期望收益相同。` },
    nx01: { q: R`手机市场：小米质量 $S_{1}=1$、苹果质量 $S_{2}=2$，边际成本均为 $2$；消费者净效用 $U=\theta S-P$，$\theta$ 在 $[4,11]$ 上均匀分布。(1) 当 $P_{1}=3,\ P_{2}=10$ 时，$\theta=4,7,11$ 的消费者各买哪种手机？哪位消费者无差异？(2) 求两种手机的需求函数；(3) 求双方同时定价的纳什均衡价格与利润。`,
      a: R`(1) 无差异条件 $\theta-3=2\theta-10\Rightarrow\theta^{*}=7$。$\theta=4<7$ 买小米（净效用 $1>8-10$）；$\theta=7$ 无差异（两边均为 4）；$\theta=11>7$ 买苹果（$8<22-10=12$）。(2) 需求 $Q_{1}=\dfrac{\theta^{*}-4}{7}=\dfrac{P_{2}-P_{1}-4}{7}$（小米）、$Q_{2}=\dfrac{11-\theta^{*}}{7}=\dfrac{11-P_{2}+P_{1}}{7}$（苹果）。(3) $\pi_{1}=(P_{1}-2)Q_{1}$、$\pi_{2}=(P_{2}-2)Q_{2}$，一阶条件 $P_{2}-2P_{1}-2=0$、$P_{1}-2P_{2}+13=0$，解得 $P_{1}^{*}=3,\ P_{2}^{*}=8$；故 $\theta^{*}=5$，$Q_{1}=\dfrac17,\ Q_{2}=\dfrac67$，$\pi_{1}=\dfrac17,\ \pi_{2}=\dfrac{36}{7}$。高质量厂商定高价、占更大市场。`,
      src: '2014 北大光华 431 真题' },
    nx02: { q: R`谷歌质量 $r_{1}$、百度质量 $r_{2}$（均 $\in[0,5]$）。谷歌收入 $200[0.5+0.05(r_{1}-r_{2})]$、成本 $c_{1}=r_{1}^{2}$；百度收入 $200[0.5+0.05(r_{2}-r_{1})]$、成本 $c_{2}=1.25r_{2}^{2}$。(1) 百度收购谷歌后的最优质量？(2) 寡头竞争（同时选质量）时 $r_{1},r_{2}$、各自利润与总质量？与 (1) 相比？(3) 谷歌投入 60 元宣传后其收入变 $200[0.75+0.05(r_{1}-r_{2})]$、百度收入变 $200[0.25+0.05(r_{2}-r_{1})]$，成本不变，谷歌会投资吗？`,
      a: R`(1) 合并后总利润 $\Pi=200-r_{1}^{2}-1.25r_{2}^{2}$（质量差项相互抵消、总收入恒为 200），故 $r_{1}^{*}=r_{2}^{*}=0$，总质量 0，利润 200。(2) 竞争下 $\pi_{1}=100+10(r_{1}-r_{2})-r_{1}^{2}$、$\pi_{2}=100+10(r_{2}-r_{1})-1.25r_{2}^{2}$，一阶条件 $10-2r_{1}=0\Rightarrow r_{1}=5$，$10-2.5r_{2}=0\Rightarrow r_{2}=4$；故 $\pi_{1}=85,\ \pi_{2}=70$，总质量 $9>0$。(3) 投资后 $\pi_{1}=150+10(r_{1}-r_{2})-r_{1}^{2}$，质量反应不变（$r_{1}=5,\ r_{2}=4$），$\pi_{1}=135$，扣除投资净得 $135-60=75<85$，故谷歌不投资。`,
      src: '2016 北大光华 431 真题' },
    nx03: { q: R`三家公司各自生产差异化产品进行 Bertrand 价格竞争。公司 $i$ 选择价格 $P_{i}\in[0,+\infty)$，销售数量 $Q_{i}=1-P_{i}+k\sum_{j\ne i}P_{j}$，边际成本 $c_{i}>0$。求每家企业的均衡价格与利润。`,
      a: R`公司 $i$ 利润 $\pi_{i}=(P_{i}-c_{i})\big(1-P_{i}+k\sum_{j\ne i}P_{j}\big)$。一阶条件 $1-2P_{i}+k\sum_{j\ne i}P_{j}+c_{i}=0$，即反应函数 $P_{i}=\dfrac{1+c_{i}+k\sum_{j\ne i}P_{j}}{2}$。令 $S=\sum_{i}P_{i}$，则 $\sum_{j\ne i}P_{j}=S-P_{i}$，代入得 $(2+k)P_{i}=1+c_{i}+kS$，即 $P_{i}=\dfrac{1+c_{i}+kS}{2+k}$。三式相加 $S=\dfrac{3+\sum_{i}c_{i}+3kS}{2+k}\Rightarrow S=\dfrac{3+\sum_{i}c_{i}}{2(1-k)}$。故 $P_{i}^{*}=\dfrac{1+c_{i}+k\cdot\frac{3+\sum_{i}c_{i}}{2(1-k)}}{2+k}$；由一阶条件 $Q_{i}=P_{i}-c_{i}$，利润 $\pi_{i}=(P_{i}^{*}-c_{i})^{2}$。`,
      src: '2018 北大光华 431 真题' },
    nx04: { q: R`某产品生产函数 $f(x_{1},x_{2})=\min\{x_{1},\,x_{2}^{\alpha}\}$（$\alpha>0$），要素价格 $w_{1}=10,\ w_{2}=20$，产品价格 $p=50$。(1) 求规模报酬递增、不变、递减时 $\alpha$ 的取值范围；(2) 求利润最大化时的要素需求函数；(3) 求成本函数。`,
      a: R`(1) $f(tx_{1},tx_{2})=\min\{tx_{1},\,t^{\alpha}x_{2}^{\alpha}\}$，与 $tf=\min\{tx_{1},\,tx_{2}^{\alpha}\}$ 相比：$\alpha>1$ 时 $t^{\alpha}>t$，规模报酬递增；$\alpha=1$ 时规模报酬不变；$0<\alpha<1$ 时 $t^{\alpha}<t$，规模报酬递减。(2) 有效生产要求 $x_{1}=x_{2}^{\alpha}$，利润 $\pi=50x_{2}^{\alpha}-10x_{2}^{\alpha}-20x_{2}=40x_{2}^{\alpha}-20x_{2}$；一阶条件 $40\alpha x_{2}^{\alpha-1}=20\Rightarrow x_{2}^{*}=(2\alpha)^{1/(1-\alpha)}$，$x_{1}^{*}=(2\alpha)^{\alpha/(1-\alpha)}$（仅 $0<\alpha<1$ 时有有限内点解；$\alpha\ge1$ 时利润无界）。(3) 生产 $q$ 需 $x_{1}=q,\ x_{2}=q^{1/\alpha}$，成本 $C(q)=10q+20q^{1/\alpha}$。`,
      src: '2015 北大光华 431 真题' },
    nx05: { q: R`企业产出 $y=16k-2k^{2}$（$k$ 为要素投入），要素自身成本为 0，期初决定 $k$，生产后政府按税率 $\tau$ 对要素征税；政府效用 $U=\tau k-0.25\tau^{2}$。(1) 求政府最优税率 $\tau$ 与要素使用量 $k$；(2) 若政府作为先行者并能信守承诺，求均衡 $k,\tau$；(3) 对比两情形说明经济学原理。`,
      a: R`(1) 企业先行、政府后动：政府给定 $k$ 最大化 $\tau k-0.25\tau^{2}$，一阶条件 $k-0.5\tau=0\Rightarrow\tau=2k$。企业预期此反应，最大化利润 $y-\tau k=16k-2k^{2}-2k^{2}=16k-4k^{2}$，$16-8k=0\Rightarrow k=2$，故 $\tau=4$，政府效用 $4\times2-0.25\times16=4$。(2) 政府先行并承诺 $\tau$：企业最大化 $16k-2k^{2}-\tau k$，$16-4k-\tau=0\Rightarrow k=\dfrac{16-\tau}{4}$；政府最大化 $U=\tau\cdot\dfrac{16-\tau}{4}-0.25\tau^{2}=4\tau-0.5\tau^{2}$，$4-\tau=0\Rightarrow\tau=4$，故 $k=3$，政府效用 $4\times3-0.25\times16=8$。(3) 税率同为 4，但政府效用 $8>4$、要素投入 $k=3>2$：政府先行并承诺税率可避免企业因预期被事后加税而压缩投资，体现先行者优势/承诺价值（子博弈精炼纳什均衡）。`,
      src: '2026 北大光华 431 真题' },
    my01: { q: R`全村 $N$ 个农户，第 $i$ 户养 $q_i$ 只羊，总数 $Q=\sum_i q_i$，每只羊价格 $p=200-Q$，养羊无成本。(1) 各户独立决策时每户养羊数、总数、价格与利润；(2) 村长组织全村先定总数再平均分利润，总数、价格与每户利润；(3) 比较 (1)(2)；(4) $N\to\infty$ 时两情形总利润如何变化；(5) 村长对每只羊征税 $t$（税款不返还），$t$ 应设为多少使每户独立养羊数等于 (2) 的最优每户数？`,
      a: R`(1) 每户最大化 $q_i(200-Q)$，一阶条件 $200-Q-q_i=0$，对称得 $$q_i=\frac{200}{N+1},\quad Q=\frac{200N}{N+1},\quad P=\frac{200}{N+1},\quad \pi_i=\frac{40000}{(N+1)^2}$$ (2) 全村最大化 $Q(200-Q)$，$200-2Q=0\Rightarrow Q=100$，$P=100$，总利润 $10000$，每户 $\frac{10000}{N}$。(3) 独立决策每户养 $\frac{200}{N+1}>\frac{100}{N}$、总数 $\frac{200N}{N+1}>100$，价格更低、每户利润 $\frac{40000}{(N+1)^2}<\frac{10000}{N}$（$N>1$）——公共草地被过度使用。(4) $N\to\infty$ 时独立决策 $Q\to200,\ P\to0$、总利润 $\to0$；组织化仍 $Q=100$、总利润 $10000$。(5) 征税后每户最大化 $q_i(200-Q)-tq_i$，对称解 $q_i=\frac{200-t}{N+1}$，令其等于 $\frac{100}{N}$：$$\frac{200-t}{N+1}=\frac{100}{N}\Rightarrow t=100\Big(1-\frac1N\Big)=\frac{100(N-1)}{N}$$`,
      src: '2022 北大光华 431 真题' },
    my02: { q: R`两合伙人努力 $e_1,e_2>0$，成本 $C(e_i)=\tfrac12 e_i^2$，公司收入 $R=e_1+e_2+\tfrac12 e_1e_2$。(1) 合作最大化 $\pi=R-C_1-C_2$，求双方努力；(2) 二人平分收入、各自最大化自己净收益，求纯策略纳什均衡；(3) 说明如何用契约缓解搭便车。`,
      a: R`(1) 合作：$\max e_1+e_2+\tfrac12e_1e_2-\tfrac12e_1^2-\tfrac12e_2^2$，一阶条件 $1+\tfrac12e_2-e_1=0$、$1+\tfrac12e_1-e_2=0$，对称得 $e_1=e_2=2$，$\pi=6-2-2=2$。(2) 平分收入：每人最大化 $\tfrac12(e_1+e_2+\tfrac12e_1e_2)-\tfrac12e_i^2$，一阶条件 $\tfrac12(1+\tfrac12e_j)-e_i=0$，对称 $$e_1=e_2=\frac23$$ 低于合作努力的 $2$——团队生产按人头平分导致搭便车。(3) 设定"收入低于阈值即没收/达标奖励"等激励契约，使个人边际收益与其努力匹配，可把合作努力变成纳什均衡。`,
      src: '2015 北大光华 431 真题' },
    my03: { q: R`垄断者同时销售两种产品，需求 $D_1(p_1,p_2)=3-\frac{p_2}{p_1^2}$、$D_2(p_1,p_2)=3-\frac{p_1}{p_2^2}$，成本 $C=y_1+y_2$。(1) 两产品是替代还是互补？(2) 写出利润（用 $p_1,p_2$ 表示）。`,
      a: R`(1) $\frac{\partial D_1}{\partial p_2}=-\frac{1}{p_1^2}<0$、$\frac{\partial D_2}{\partial p_1}=-\frac{1}{p_2^2}<0$，即一种商品涨价使另一种需求下降，故两产品为**互补品**。(2) $$\pi=(p_1-1)D_1+(p_2-1)D_2=(p_1-1)\Big(3-\frac{p_2}{p_1^2}\Big)+(p_2-1)\Big(3-\frac{p_1}{p_2^2}\Big)$$ 多产品垄断须同时关于 $p_1,p_2$ 最大化（互补品定价需考虑价格联动）。`,
      src: '2016 北大光华 431 真题' },
    my04: { q: R`明天有晴、雨两种状态。晴天消费者确定获得 $y_1$ 碗热干面；雨天收益 $y_2$ 随机（一半概率 $y_H$、一半 $y_L$，$y_H>y_L$）。偏好 $U=\min\{E(c_1),E(c_2)\}$（$c_1,c_2$ 为晴、雨状态消费）。公司以价格 $p_1,p_2$ 出售晴、雨状态的热干面期货（今天支付 $p_s$，若对应状态发生则得 1 碗）。消费者今天无初始收益。(1) 写预算约束；(2) 求 $x_1$ 表达式；(3) $x_1$ 一定为负吗？(4) $p_1,p_2$ 都翻倍对 $x_1$ 有何影响？`,
      a: R`(1) 自融资：$$p_1x_1+p_2x_2=0$$ 即 $x_2=-\frac{p_1}{p_2}x_1$。(2) 状态消费 $c_1=y_1+x_1$、$c_2=y_2+x_2$，$E(c_1)=y_1+x_1$、$E(c_2)=E[y_2]+x_2=\frac{y_H+y_L}{2}+x_2$。$U=\min\{E(c_1),E(c_2)\}$ 最优需二者相等：$$y_1+x_1=\frac{y_H+y_L}{2}-\frac{p_1}{p_2}x_1\Rightarrow x_1=\frac{\big(\frac{y_H+y_L}{2}-y_1\big)p_2}{p_1+p_2}$$ (3) 不一定为负：$x_1$ 的符号取决于 $E[y_2]$ 与 $y_1$ 的大小（晴天禀赋高则做空 $x_1<0$，反之做多）。(4) $x_1$ 关于 $(p_1,p_2)$ 零次齐次，两价格同时翻倍**不变** $x_1$（只取决于相对价格）。`,
      src: '2018 北大光华 431 真题' },
    my05: { q: R`三种情形分别判断：(1) 消费者效用 $U=b^{0.5}c^{0.5}$，初始禀赋 2 公斤牛肉、3 公斤胡萝卜，可在市场出售禀赋，是否存在一组价格使她愿意直接消费自己的禀赋？(2) 消费者效用 $U=\min\{b,c\}$，禀赋 2 公斤薯片、3 升饮料，同上问；(3) 护林员住深山，吃牛肉面需开车去 30 公里外的面馆，每天必须先消耗 6 升汽油、余钱全买牛肉面，他的偏好可用无差异曲线描述吗？`,
      a: R`(1) 禀赋点 $MRS=\frac{MU_b}{MU_c}=\frac{c}{b}=\frac32$。直接消费禀赋最优需 $MRS=\frac{p_b}{p_c}$，故取 $\frac{p_b}{p_c}=\frac32$ 时禀赋即最优——存在（价格比恰等于禀赋点 $MRS$）。(2) 完全互补品最优必有 $b=c$，而禀赋 $(2,3)$ 有 $b\neq c$，故对任何正价格都不直接消费禀赋（会卖出饮料换薯片直到 $b=c$）。(3) 可以。6 升汽油是固定的"必要消耗"，超过 6 升后效用只取决于牛肉面数量，偏好完整、可传递，可用无差异曲线表示（对牛肉面数量而言为水平/垂直线族）。`,
      src: '2017 北大光华 431 真题' },
    my06: { q: R`A、B 两城市劳动人口均为 $L$，产出 $y_a=aLh_a$、$y_b=bLh_b$（$a>b$），把 $L$ 名劳动力教育到 $h$ 水平的总成本 $cLh^2$。(1) 各城市最大化本地净产出，求最优教育水平；(2) $m$ 名 B 市劳工受教育后迁往 A（教育水平 $h_b$ 不变，B 无法收回成本），求两地最优教育水平及与 (1) 相比的变化；(3) 中央政府承担教育成本、最大化两地总净产出，求最优教育水平及与 (1) 的变化。`,
      a: R`(1) $\max aLh_a-cLh_a^2\Rightarrow h_a=\frac{a}{2c}$；同理 $h_b=\frac{b}{2c}$。(2) 迁移后 A 产出 $a(Lh_a+mh_b)$、B 产出 $b(L-m)h_b$，成本仍各付 $cLh_i^2$。A：$aL-2cLh_a=0\Rightarrow h_a=\frac{a}{2c}$ 不变；B：$b(L-m)-2cLh_b=0\Rightarrow h_b=\frac{b(L-m)}{2cL}<\frac{b}{2c}$，即 B 预期人才流失、减少教育投入。(3) 中央政府最大化 $a(Lh_a+mh_b)+b(Lh_b-mh_b)-cLh_a^2-cLh_b^2$：$h_a=\frac{a}{2c}$ 不变，$$h_b=\frac{am+b(L-m)}{2cL}>\frac{b}{2c}$$ 中央政府把迁移带给 A 的外部收益 $am$ 内部化，故 $h_b$ 高于 (1)——迁移造成财政外部性，需上级政府协调。`,
      src: '2019 北大光华 431 真题' },
    te01: [{ q: R`效用 $U=x_1^{1/2}x_2^{1/2}$，$p_1=1,\ p_2=4,\ m=100$，求最优消费组合与间接效用。`,
      a: R`$MRS=\dfrac{MU_1}{MU_2}=\dfrac{x_2}{x_1}=\dfrac{p_1}{p_2}=\dfrac14\Rightarrow x_1=4x_2$；预算 $x_1+4x_2=100$ 代入得 $8x_2=100\Rightarrow x_2=12.5,\ x_1=50$。间接效用 $V=\sqrt{50\times12.5}=25$。` },
    { q: R`消费者采购加湿器 $x$ 与净化器 $y$，效用 $U=x^{1/3}y^{2/3}$，加湿器价格 $P_x=1$、净化器价格 $P_y=4$，总预算 $M=24$。(1) 求两种商品的最优采购数量；(2) 政府对净化器厂商征税使其价格变为 $4t_1\ (t_1>1)$，求使净化器采购量降为 (1) 的 $50\%$ 的 $t_1$；(3) 若改征所得税使总预算变为 $24t_2\ (0<t_2<1)$，求使净化器采购量降为 $50\%$ 的 $t_2$；(4) 哪种征税方案下消费者效用更高？有何政策启示？`,
      a: R`(1) 柯布-道格拉斯需求（$a=\tfrac13,\ b=\tfrac23$）：$$x^{*}=\frac{a}{a+b}\cdot\frac{M}{P_x}=\frac13\cdot24=8,\qquad y^{*}=\frac{b}{a+b}\cdot\frac{M}{P_y}=\frac23\cdot\frac{24}{4}=4$$ (2) 价格变为 $4t_1$ 后：$$y=\frac23\cdot\frac{24}{4t_1}=\frac{4}{t_1}$$ 令 $\dfrac{4}{t_1}=2\Rightarrow t_1=2$（净化器价格升至 $8$），此时 $x=\dfrac13\cdot24=8$ 不变。(3) 预算变为 $24t_2$：$$y=\frac23\cdot\frac{24t_2}{4}=4t_2$$ 令 $4t_2=2\Rightarrow t_2=\dfrac12$，此时 $x=\dfrac13\cdot(24\times\tfrac12)=4$。(4) 方案(2)效用 $$U_2=8^{1/3}\cdot2^{2/3}=2^{5/3}$$；方案(3)效用 $$U_3=4^{1/3}\cdot2^{2/3}=2^{4/3}$$。因 $U_2=2^{1/3}U_3>U_3$，**商品税方案效用更高**。启示：定向商品税只抬高净化器价格，消费者可转向多买加湿器（$x$ 保持 $8$）、损失较小；所得税则按比例削减总预算，"一刀切"地同时压缩未被征税的加湿器消费，在达成同一"减购净化器"目标时对消费者福利损害更大。`,
      src: '2022 北大光华 431 真题' } ],
    te02: [{ q: R`生产函数 $Q=L^{1/2}K^{1/2}$，$w=1,\ r=4$。求生产 $Q=10$ 的最小成本及成本函数 $C(Q)$。`,
      a: R`$\dfrac{MP_L}{MP_K}=\dfrac{K}{L}=\dfrac{w}{r}=\dfrac14\Rightarrow L=4K$；又 $Q=(4K)^{1/2}K^{1/2}=2K\Rightarrow K=\dfrac{Q}{2},\ L=2Q$。$C(Q)=wL+rK=2Q+4\cdot\dfrac{Q}{2}=4Q$，故生产 $Q=10$ 的最小成本为 $40$。` },
    { q: R`已知生产函数 $f(x_1,x_2)=\min\{x_1,\ x_2^{\alpha}\}$（$\alpha>0$），要素价格 $w_1=10,\ w_2=20$，产品价格 $p=50$。(1) 求规模报酬递增、不变、递减时 $\alpha$ 的取值范围；(2) 求利润最大化时的要素需求函数；(3) 求成本函数；(4) 说明 (2)(3) 如何依赖于 $\alpha$。`,
      a: R`(1) $$f(tx_1,tx_2)=\min\{tx_1,\ t^{\alpha}x_2^{\alpha}\}$$ 与 $$tf=\min\{tx_1,\ tx_2^{\alpha}\}$$ 相比：$\alpha>1$ 时 $t^{\alpha}>t$，规模报酬递增；$\alpha=1$ 不变；$0<\alpha<1$ 递减。(2) 有效生产要求 $x_1=x_2^{\alpha}$（浪费无益），利润 $$\pi=50x_2^{\alpha}-10x_2^{\alpha}-20x_2=40x_2^{\alpha}-20x_2$$ 一阶条件 $$40\alpha\,x_2^{\alpha-1}=20\Rightarrow x_2^{*}=(2\alpha)^{1/(1-\alpha)},\quad x_1^{*}=(2\alpha)^{\alpha/(1-\alpha)}$$ 仅 $0<\alpha<1$ 时有有限内点解（$\alpha\ge1$ 时规模报酬非减、利润无界）。(3) 生产 $q$ 需 $x_1=q,\ x_2=q^{1/\alpha}$：$$C(q)=10q+20q^{1/\alpha}$$ (4) $\alpha$ 决定规模报酬性质：$\alpha>1$ 时平均成本随 $q$ 递减（规模经济）、利润最大化无界；$\alpha<1$ 时成本凸、利润最大化有内点解；要素需求与成本函数都经 $x_2=q^{1/\alpha}$ 依赖 $\alpha$。`,
      src: '2015 北大光华 431 真题' } ],
    te03: [{ q: R`市场需求 $P=100-Q$，$MC=20$。分别求垄断与完全竞争的最优产量与价格。`,
      a: R`垄断：$MR=100-2Q=20\Rightarrow Q_M=40,\ P_M=60$；完全竞争：$P=MC$，$100-Q=20\Rightarrow Q_C=80,\ P_C=20$。垄断产量更少、价格更高，产生无谓损失。` },
    { q: R`4 个生产同质产品的厂商，边际成本均为 $10$；代表性消费者购买 $x$ 单位该产品的效用为 $20x-5x^2$。(1) 各厂商独立决策（古诺）时的总供给；(2) 各厂商合谋时的总供给；(3) (1)(2) 的总消费者剩余相差多少？为什么？`,
      a: R`由 $P=MU$ 得逆需求 $$P=20-10x=20-10Q$$ (1) 古诺：$$\pi_i=(20-10Q)q_i-10q_i=(10-10Q)q_i$$ 一阶条件 $$10-10Q-10q_i=0\Rightarrow 1-Q-q_i=0$$ 对称 $Q=4q_i$：$1-5q_i=0\Rightarrow q_i=0.2$，总供给 $$Q_C=4\times0.2=0.8,\quad P=12$$ (2) 合谋：$$\Pi=(20-10Q)Q-10Q=10Q-10Q^{2}$$ 令 $10-20Q=0\Rightarrow Q_M=0.5,\quad P=15$。(3) $$CS_C=\int_{0}^{0.8}(20-10x)\,dx-12\times0.8=3.2$$ $$CS_M=\int_{0}^{0.5}(20-10x)\,dx-15\times0.5=1.25$$ 相差 $$3.2-1.25=1.95$$ 合谋限产提价，把消费者剩余转化为垄断利润并造成无谓损失。`,
      src: '2024 北大光华 431 真题' } ],
    te04: [{ q: R`囚徒困境：两人都不招供各判 1 年（$-1$），都招供各判 5 年（$-5$），一人招供一人不招则招供者释放（$0$）、不招者判 10 年（$-10$）。求纳什均衡。`,
      a: R`给定对方不招，招供 $0>$ 不招 $-1$；给定对方招供，招供 $-5>$ 不招 $-10$，故「招供」是占优策略，纳什均衡为（招供，招供）$(-5,-5)$，劣于（不招，不招）$(-1,-1)$——个体理性导致集体非理性。` },
    { q: R`两个股票投机者同时选择是否卖空某股票。卖空者支付成本 $c=2$，收益 $v=1.5N$（$N$ 为卖空人数）；不卖空者成本与收益均为 $0$。(1) 求全部纯策略纳什均衡；(2) 求对称混合策略纳什均衡。`,
      a: R`(1) 支付矩阵（行/列均为「卖空/不卖空」）：都卖空 $$(1.5\times2-2,\,1.5\times2-2)=(1,1)$$ 仅一方卖空时，卖空者 $1.5\times1-2=-0.5$、对方 $0$；都不卖空 $(0,0)$。最优反应：对手卖空→我卖空得 $1>0$；对手不卖空→我不卖空得 $0>-0.5$。故纯策略纳什均衡为 **（卖空，卖空）** 与 **（不卖空，不卖空）**。(2) 设对手以概率 $q$ 卖空，则我卖空的期望支付 $$q\times1+(1-q)\times(-0.5)=1.5q-0.5$$ 不卖空为 $0$。令无差异：$$1.5q-0.5=0\Rightarrow q=\dfrac13$$ 故对称混合策略纳什均衡为：双方各以 $\dfrac13$ 概率卖空、$\dfrac23$ 概率不卖空。`,
      src: '2025 北大光华 431 真题' } ],
    te05: [{ q: R`两消费者 $A,B$ 效用 $U_A=x_Ay_A,\ U_B=x_By_B$，总禀赋 $(\bar x,\bar y)=(10,10)$。求契约曲线。`,
      a: R`令 $MRS_A=\dfrac{y_A}{x_A}=MRS_B=\dfrac{y_B}{x_B}$，且 $x_B=10-x_A,\ y_B=10-y_A$，得 $\dfrac{y_A}{x_A}=\dfrac{10-y_A}{10-x_A}\Rightarrow 10y_A-x_Ay_A=10x_A-x_Ay_A\Rightarrow y_A=x_A$，即契约曲线为对角线 $y_A=x_A$。` },
    { q: R`两种商品 $x,y$。小丽效用 $u=x+y$（完全替代），小贾效用 $u=\max\{x,y\}$。(1) 用无差异曲线在埃奇沃斯盒中画出两人偏好；(2) 猜想均衡价格关系；(3) 猜想均衡分配结果。`,
      a: R`(1) 小丽 $u=x+y$：无差异曲线为斜率 $-1$ 的直线（完全替代品）；小贾 $u=\max\{x,y\}$：无差异曲线为沿两轴的直角折线（折角在 $x=y$ 处），偏好集非凸。(2) 小丽 $MRS_{xy}=1$ 恒定，要有内点解需 $$\frac{p_x}{p_y}=MRS=1$$ 故均衡价格 $p_x=p_y$。(3) 给定 $p_x=p_y$，小贾在 $x=y$ 的折角处（或任一轴上）无差异——他只需「两种商品中较多的一种」，故均衡时小贾消费等量 $(x,x)$，小丽消费预算线上其余部分（沿直线 $x+y$ 分配）。因小贾偏好非凸，瓦尔拉斯均衡的存在性与福利定理需注意凸性前提。`,
      src: '2018 北大光华 431 真题' } ],
    te06: [{ q: R`某工厂排污，私人边际成本 $MC=2Q$，外部边际成本 $MD=Q$，需求 $P=30-Q$。求市场均衡产量、社会最优产量与庇古税。`,
      a: R`市场均衡 $30-Q=2Q\Rightarrow Q=10$；社会边际成本 $=2Q+Q=3Q$，社会最优 $30-Q=3Q\Rightarrow Q^{*}=7.5$；庇古税 $t=MD(Q^{*})=7.5$，征税后 $2Q+7.5=30-Q\Rightarrow Q=7.5=Q^{*}$。` },
    { q: R`小镇上有 $N$ 个居民，总财富为 $1$，财富在 $N$ 个居民中平均分配。每个居民选择将财富拿出 $y$ 用于私人消费、$x$ 用于环保支出（环保支出为全镇公共品）。效用 $u=\sqrt{Xy}$，其中 $X$ 为全镇环保总支出（所有居民环保支出之和）。(1) 求均衡时全镇环保总支出 $X$，并说明其随 $N$ 如何变化；(2) 该结果反映了什么经济学原理？`,
      a: R`每人预算 $x_i+y_i=\dfrac1N$，$X=\sum_i x_i$。(1) 居民 $i$ 最大化 $\sqrt{(X_{-i}+x_i)\,y_i}$，即最大化 $\tfrac12\ln X+\tfrac12\ln y_i$，一阶条件 $$\frac{1}{X}=\frac{1}{y_i}\Rightarrow y_i=X$$ 即每人私人消费等于全镇公共品总量。加总：$\sum_i y_i=1-X$ 且 $\sum_i y_i=NX$，故 $$NX=1-X\Rightarrow X=\frac{1}{N+1}$$ 随 $N$ 增大而**递减**——受益者越多、搭便车越严重。(2) 社会最优满足萨缪尔森条件 $$\sum_i MRS_i=MRT=1$$ 其中 $$MRS_i=\frac{\partial u_i/\partial X}{\partial u_i/\partial y_i}=\frac{y_i}{X}$$ 故 $$\sum_i\frac{y_i}{X}=\frac{1-X}{X}=1\Rightarrow X^{*}=\frac12$$ 均衡 $X=\dfrac{1}{N+1}<\dfrac12$（$N>1$）——公共物品的非排他性使个人低估环保支出的社会收益、倾向搭便车，导致公共品供给不足。`,
      src: '2025 北大光华 431 真题' } ],
    te07: [{ q: R`效用 $U=x_1x_2$，$p_1=p_2=1$，收入 $m=20$。若 $p_1$ 升至 $4$，求 $x_1$ 的斯勒茨基替代效应与收入效应。`,
      a: R`柯布-道格拉斯需求 $x_1=\frac{m}{2p_1}$。初始 $x_1(1,20)=10$；价格变动后 $x_1(4,20)=2.5$，总效应 $2.5-10=-7.5$。为保持原消费束 $(10,10)$ 可负担，需补偿 $\Delta m=x_1\Delta p_1=10\times3=30$，即 $m'=50$；此时 $x_1(4,50)=6.25$。故替代效应 $=6.25-10=-3.75$，收入效应 $=2.5-6.25=-3.75$，总效应 $=-7.5$。` },
      { q: R`效用 $U=x^{1/2}y^{1/2}$，$p_x=1,\ p_y=2,\ m=40$。求 $p_x$ 从 $1$ 涨到 $4$ 时 $x$ 的希克斯替代效应与收入效应。`,
        a: R`马歇尔需求 $x=\frac{m}{2p_x}$：初始 $x=20$；变动后 $x=5$。初始效用 $U=20^{1/2}\cdot10^{1/2}=\sqrt{200}$，希克斯需求 $x^h=\left(\frac{p_y}{p_x}\right)^{1/2}U=\left(\frac{2}{4}\right)^{1/2}\sqrt{200}=10$。希克斯替代效应 $=10-20=-10$；收入效应 $=5-10=-5$（正常品，两效应同向）。` } ],
    te08: [{ q: R`某人财富 $w=100$，效用 $u=\sqrt{w}$。面临以概率 $0.2$ 损失 $60$ 的风险。求公平保费、确定性等价与风险溢价。`,
      a: R`$EU=0.8\sqrt{100}+0.2\sqrt{40}=8+0.2\times6.3249\approx9.265$。公平保费 $=pL=0.2\times60=12$，全额投保后确定性财富 $88$。确定性等价 $CE$ 满足 $\sqrt{CE}=9.265\Rightarrow CE\approx85.84$。期望财富 $E(w)=0.8\times100+0.2\times40=88$。风险溢价 $=88-85.84=2.16$（愿比公平保费多付 $2.16$ 消除风险）。` },
      { q: R`风险厌恶者财富 $w=100$，以概率 $p=0.1$ 损失 $L=50$，效用 $u=\ln w$。保费率为 $q$（投保 $I$ 支付 $qI$）。求最优投保额。`,
        a: R`投保后：不损失时财富 $w_0=100-qI$，损失时 $w_1=100-50+I-qI=50+(1-q)I$。期望效用 $EU=0.9\ln(100-qI)+0.1\ln(50+(1-q)I)$。一阶条件$$\frac{dEU}{dI}=0.9\frac{-q}{100-qI}+0.1\frac{1-q}{50+(1-q)I}=0$$当保费公平（$q=p=0.1$）时代入解得 $I=50$，即全额投保。` } ],
    te09: [{ q: R`生产函数 $Q=L^{1/2}K^{1/2}$，产品价格 $p=10$，工资 $w=2$，资本 $K=25$ 固定。求利润最大化的劳动需求。`,
      a: R`短期 $Q=L^{1/2}\cdot25^{1/2}=5L^{1/2}$，$MP_L=\frac{dQ}{dL}=\frac{5}{2}L^{-1/2}$。利润最大化 $VMP_L=p\cdot MP_L=w$：$$10\cdot\frac{5}{2}L^{-1/2}=2\Rightarrow L^{-1/2}=\frac{2}{25}\Rightarrow L=\left(\frac{25}{2}\right)^{2}=156.25$$` },
      { q: R`某行业劳动供给 $L^s=10w$，劳动需求 $L^d=200-10w$。求均衡工资；若政府规定最低工资 $w_{\min}=15$，分析失业。`,
        a: R`均衡 $10w=200-10w\Rightarrow w^{*}=10,\ L^{*}=100$。若 $w_{\min}=15$：供给 $L^s=150$、需求 $L^d=200-150=50$，出现失业 $150-50=100$（最低工资高于均衡工资导致供给过剩）。` } ],
  };

